parameters.jsCode:
// ==========================================================
// Bayyinah | Evaluate Retrieval Sufficiency
// تقييم أولي لنتائج Qdrant قبل اتخاذ قرار الكفاية الدلالية
//
// Embedding:
// Jina Embeddings v3
//
// Vector:
// 1024 dimensions
//
// Similarity:
// Cosine
// ==========================================================

const input = $input.first().json;


// ==========================================================
// 1) قراءة نتائج Qdrant
// ==========================================================

const points =
  Array.isArray(input.result?.points)
    ? input.result.points
    : [];


if (points.length === 0) {

  return [{
    json: {

      sufficient: false,

      status:
        "INSUFFICIENT",

      reason:
        "لم يتم العثور على أي مادة في قاعدة المعرفة.",

      best_score:
        0,

      retrieved_count:
        0,

      usable_count:
        0,

      evidence:
        []
    }
  }];
}


// ==========================================================
// 2) ترتيب النتائج حسب درجة التشابه
// ==========================================================

const sortedPoints =
  [...points].sort(
    (a, b) =>
      Number(b.score || 0) -
      Number(a.score || 0)
  );


// ==========================================================
// 3) إزالة النتائج الضعيفة
//
// Jina Embeddings v3 + Cosine Similarity
//
// هذه ليست درجة "الكفاية النهائية".
// هي فقط بوابة أولية تمنع النتائج شديدة الضعف
// من الوصول إلى Evidence Judge.
//
// الكفاية الدلالية النهائية يقررها Evidence Judge.
// ==========================================================

const MIN_USABLE_SCORE = 0.35;


const usablePoints =
  sortedPoints.filter(
    point =>
      Number(point.score || 0) >=
      MIN_USABLE_SCORE
  );


// ==========================================================
// 4) أخذ أفضل 5 نتائج قابلة للفحص
// ==========================================================

const topResults =
  usablePoints.slice(0, 5);


const bestScore =
  Number(
    sortedPoints[0]?.score || 0
  );


// ==========================================================
// 5) إذا لم يبق أي دليل قابل للفحص
// ==========================================================

if (topResults.length === 0) {

  return [{
    json: {

      sufficient: false,

      status:
        "INSUFFICIENT",

      reason:
        "نتائج الاسترجاع ضعيفة جدًا ولا توجد مادة مناسبة لإرسالها للتقييم الدلالي.",

      best_score:
        bestScore,

      retrieved_count:
        points.length,

      usable_count:
        0,

      evidence:
        []
    }
  }];
}


// ==========================================================
// 6) تجهيز الأدلة
//
// يدعم Metadata القديم والجديد
// ==========================================================

const evidence =
  topResults.map(point => {

    const p =
      point.payload || {};


    const printedPages =
      Array.isArray(p.printed_pages)
        ? p.printed_pages
        : [];


    const pdfPages =
      Array.isArray(p.pdf_pages)
        ? p.pdf_pages
        : [];


    return {

      // ======================================
      // درجة التشابه
      // ======================================

      score:
        Number(point.score || 0),


      // ======================================
      // النص المسترجع
      // ======================================

      content:
        p.content || "",


      // ======================================
      // بيانات المصدر
      // ======================================

      source_type:
        p.source_type || "book",

      source_title:
        p.source_title ||
        p.book_title ||
        p.source_name ||
        "",


      // للتوافق مع النظام القديم

      book_title:
        p.book_title ||
        p.source_title ||
        p.source_name ||
        "",

      source_name:
        p.source_name ||
        p.source_title ||
        p.book_title ||
        "",

      document_id:
        p.document_id || "",


      // ======================================
      // المسألة / القسم
      // ======================================

      issue_number:
        p.issue_number ?? null,

      issue_title:
        p.issue_title || "",

      section_title:
        p.section_title ||
        p.issue_title ||
        "",


      // ======================================
      // الصفحات
      // ======================================

      printed_pages:
        printedPages,

      pdf_pages:
        pdfPages,


      // ======================================
      // دعم حقول الصفحات القديمة
      // ======================================

      page_start:
        p.page_start ??
        (
          printedPages.length > 0
            ? printedPages[0]
            : (
                pdfPages.length > 0
                  ? pdfPages[0]
                  : null
              )
        ),

      page_end:
        p.page_end ??
        (
          printedPages.length > 0
            ? printedPages[
                printedPages.length - 1
              ]
            : (
                pdfPages.length > 0
                  ? pdfPages[
                      pdfPages.length - 1
                    ]
                  : null
              )
        ),


      // ======================================
      // بيانات Chunk
      // ======================================

      chunk_id:
        p.chunk_id || "",

      chunk_index:
        p.chunk_index ?? null,

      parent_id:
        p.parent_id || "",

      docling_refs:
        Array.isArray(p.docling_refs)
          ? p.docling_refs
          : [],


      // ======================================
      // Metadata الجديدة
      // ======================================

      language:
        p.language || "ar",

      dataset:
        p.dataset || "",

      processing_version:
        p.processing_version || "",

      rag_ready:
        p.rag_ready ?? null
    };
  });


// ==========================================================
// 7) النتيجة
//
// وجود نتائج فوق 0.35 لا يعني أن الأدلة كافية للإجابة.
//
// هذه العقدة تقول فقط:
// "هناك نتائج تستحق أن يفحصها Evidence Judge."
//
// القرار النهائي للكفاية يبقى لـ Evidence Judge.
// ==========================================================

return [{
  json: {

    sufficient:
      true,

    status:
      "READY_FOR_SEMANTIC_EVALUATION",

    reason:
      "تم العثور على نتائج قابلة للفحص. يجب تقييم كفايتها دلاليًا بناءً على محتواها، وليس على درجة التشابه وحدها.",

    best_score:
      bestScore,

    retrieved_count:
      points.length,

    usable_count:
      topResults.length,

    evidence
  }
}];

/**
 * Bayyinah | Parse Evidence Decision
 *
 * Functions:
 * 1. Parse Evidence Judge JSON.
 * 2. Validate decisions and flags.
 * 3. Preserve ZERO-BASED evidence indexes.
 * 4. Retrieve original evidence.
 * 5. Verify exact hadith identity when authenticity
 *    of a specific hadith is requested.
 * 6. Prevent SUPPORTED if the requested hadith
 *    lacks direct authentication evidence.
 *
 * No changes to existing node connections.
 */

const input = $input.first().json;

// =====================================================
// 1. Parse Evidence Judge
// =====================================================

let raw = input.text ?? input.output ?? "";

raw = String(raw)
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

let result;

try {
  result = JSON.parse(raw);
} catch (error) {
  throw new Error(
    "تعذر قراءة قرار Evidence Judge كـ JSON:\n" +
    raw
  );
}

const allowedDecisions = [
  "SUPPORTED",
  "NEEDS_EXTERNAL_SEARCH",
  "NEEDS_HUMAN_REVIEW"
];

if (!allowedDecisions.includes(result.decision)) {
  throw new Error(
    "قرار Evidence Judge غير صحيح: " +
    result.decision
  );
}

// =====================================================
// 2. Retrieve original question
// =====================================================

let incoming = {};

try {
  incoming =
    $("Prepare Incoming Question")
      .first()
      .json || {};
} catch (error) {
  incoming = {};
}

const question = String(
  incoming.question ??
  result.question ??
  ""
).trim();

// =====================================================
// 3. Retrieve original RAG evidence
// =====================================================

let retrievalData = {};

try {
  retrievalData =
    $("Evaluate Retrieval Sufficiency")
      .first()
      .json || {};
} catch (error) {
  retrievalData = {};
}

const allEvidence = Array.isArray(
  retrievalData.evidence
)
  ? retrievalData.evidence
  : [];

// =====================================================
// 4. Validate ZERO-BASED indexes
// =====================================================

const rawIndexes = Array.isArray(
  result.recommended_evidence_indexes
)
  ? result.recommended_evidence_indexes
  : [];

const recommendedIndexes = [
  ...new Set(
    rawIndexes
      .map(value => Number(value))
      .filter(index =>
        Number.isInteger(index) &&
        index >= 0 &&
        index < allEvidence.length
      )
  )
];

let selectedEvidence = recommendedIndexes
  .map(index => allEvidence[index])
  .filter(Boolean);

// Preserve previous SUPPORTED fallback
if (
  result.decision === "SUPPORTED" &&
  selectedEvidence.length === 0
) {
  selectedEvidence = allEvidence;
}

// =====================================================
// 5. Arabic normalization
// =====================================================

function normalizeArabic(value) {
  return String(value ?? "")
    .normalize("NFKC")
    .replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g, "")
    .replace(/\u0640/g, "")
    .replace(/[أإآٱ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ؤ/g, "و")
    .replace(/ئ/g, "ي")
    .replace(/ة/g, "ه")
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// =====================================================
// 6. Detect questions asking about authenticity
//    of a SPECIFIC hadith
// =====================================================

function extractRequestedHadith(text) {
  const normalizedQuestion = normalizeArabic(text);

  const mentionsHadith =
    /(?:حديث|الحديث)/.test(normalizedQuestion);

  const asksAuthenticity =
    /(?:ما صحه|مدي صحه|هل .*?(?:صحيح|ضعيف|ثابت)|درجه.*?حديث|تخريج.*?حديث|ثبوت.*?حديث|صحه.*?حديث)/.test(
      normalizedQuestion
    );

  if (!mentionsHadith || !asksAuthenticity) {
    return null;
  }

  let phrase = "";

  // Arabic quotation marks
  const arabicQuote = text.match(
    /«([^»]{4,180})»/
  );

  if (arabicQuote) {
    phrase = arabicQuote[1];
  }

  // English quotation marks
  if (!phrase) {
    const englishQuote = text.match(
      /["“]([^"”]{4,180})["”]/
    );

    if (englishQuote) {
      phrase = englishQuote[1];
    }
  }

  // Unquoted hadith phrase
  if (!phrase) {
    const unquoted = text.match(
      /(?:حديث|الحديث)\s+(.+?)(?=[؟?،,؛;.]|\s+وما\s+|$)/
    );

    if (unquoted) {
      phrase = unquoted[1];
    }
  }

  phrase = normalizeArabic(phrase);

  const words = phrase.split(" ").filter(Boolean);

  if (
    words.length < 2 ||
    words.length > 18 ||
    phrase.length > 180
  ) {
    return null;
  }

  return phrase;
}

// =====================================================
// 7. Verify hadith identity and authentication
//
// Important:
// Authentication of a different hadith is not
// evidence for the hadith in the question.
//
// The exact phrase and authentication evidence
// must refer to the same retrieved passage.
// =====================================================

function verifyHadithEvidence(
  requestedHadith,
  evidence
) {
  const matchedIndexes = [];
  const authenticatedIndexes = [];

  const authenticationPattern =
    /(?:متفق عليه|رواه البخاري|رواه مسلم|اخرجه البخاري|اخرجه مسلم|صحيح البخاري|صحيح مسلم|البخاري ومسلم|حكم المحدث صحيح|اسناده صحيح|سنده صحيح|حديث صحيح|حسن صحيح|صححه الالباني)/;

  for (let i = 0; i < evidence.length; i++) {
    const item = evidence[i] || {};

    const content = normalizeArabic(
      item.content ?? ""
    );

    if (!content) {
      continue;
    }

    const paddedContent = " " + content + " ";

    const paddedHadith =
      " " + requestedHadith + " ";

    const position = paddedContent.indexOf(
      paddedHadith
    );

    // Exact normalized hadith phrase is required.
    if (position === -1) {
      continue;
    }

    matchedIndexes.push(i);

    // Inspect nearby text, not unrelated references
    // elsewhere in the book chunk.
    const start = Math.max(
      0,
      position - 300
    );

    const end = Math.min(
      paddedContent.length,
      position + paddedHadith.length + 300
    );

    const context = paddedContent.slice(
      start,
      end
    );

    const title = normalizeArabic(
      item.source_title ??
      item.book_title ??
      item.source_name ??
      ""
    );

    const canonicalHadithCollection =
      /^(?:صحيح البخاري|صحيح مسلم)$/.test(
        title
      );

    const directlyAuthenticated =
      authenticationPattern.test(context) ||
      canonicalHadithCollection;

    if (directlyAuthenticated) {
      authenticatedIndexes.push(i);
    }
  }

  return {
    exact_text_found:
      matchedIndexes.length > 0,

    direct_authentication_found:
      authenticatedIndexes.length > 0,

    matched_evidence_indexes:
      matchedIndexes,

    authenticated_evidence_indexes:
      authenticatedIndexes
  };
}

// =====================================================
// 8. Apply hadith integrity guard
// =====================================================

const requestedHadith =
  extractRequestedHadith(question);

const originalDecision =
  result.decision;

let finalDecision =
  originalDecision;

let finalReason =
  String(result.reason || "");

let supportedPoints = Array.isArray(
  result.supported_points
)
  ? result.supported_points
  : [];

let missingPoints = Array.isArray(
  result.missing_points
)
  ? [...result.missing_points]
  : [];

const hadithGuard = {
  applicable: Boolean(requestedHadith),

  requested_hadith:
    requestedHadith || "",

  exact_text_found: null,

  direct_authentication_found: null,

  matched_evidence_indexes: [],

  authenticated_evidence_indexes: [],

  original_decision:
    originalDecision,

  final_decision:
    originalDecision,

  overridden: false,

  reason: ""
};

if (requestedHadith) {
  const verification = verifyHadithEvidence(
    requestedHadith,
    allEvidence
  );

  hadithGuard.exact_text_found =
    verification.exact_text_found;

  hadithGuard.direct_authentication_found =
    verification.direct_authentication_found;

  hadithGuard.matched_evidence_indexes =
    verification.matched_evidence_indexes;

  hadithGuard.authenticated_evidence_indexes =
    verification.authenticated_evidence_indexes;

  const sufficientAuthentication =
    verification.exact_text_found &&
    verification.direct_authentication_found;

  if (
    originalDecision === "SUPPORTED" &&
    !sufficientAuthentication
  ) {
    finalDecision =
      "NEEDS_EXTERNAL_SEARCH";

    hadithGuard.overridden = true;

    const problem =
      !verification.exact_text_found
        ? "لم يظهر نص الحديث المطلوب نفسه في الأدلة المسترجعة."
        : "ظهر نص الحديث، لكن لم يوجد توثيق مباشر وكافٍ لصحته في سياقه.";

    hadithGuard.reason = problem;

    finalReason =
      "قاعدة التحقق من هوية الحديث: " +
      problem +
      " لا يجوز اعتماد توثيق حديث آخر " +
      "لمجرد تشابه الموضوع أو المعنى. " +
      "يلزم البحث في المصادر الحديثية المعتمدة.";

    // Do not propagate incorrect claims that the
    // requested hadith has been authenticated.
    supportedPoints = [];

    missingPoints = [
      ...new Set([
        ...missingPoints,
        "توثيق مباشر لصحة الحديث المحدد: " +
        requestedHadith
      ])
    ];
  }
}

hadithGuard.final_decision =
  finalDecision;

// =====================================================
// 9. Consistent decision flags
// =====================================================

const expectedFlags = {
  SUPPORTED: {
    evidence_sufficient: true,
    needs_external_search: false,
    needs_human_review: false
  },

  NEEDS_EXTERNAL_SEARCH: {
    evidence_sufficient: false,
    needs_external_search: true,
    needs_human_review: false
  },

  NEEDS_HUMAN_REVIEW: {
    evidence_sufficient: false,
    needs_external_search: false,
    needs_human_review: true
  }
};

const flags = expectedFlags[finalDecision];

// =====================================================
// 10. Confidence
// =====================================================

let confidence = Number(
  result.confidence
);

if (!Number.isFinite(confidence)) {
  confidence = 0;
}

confidence = Math.max(
  0,
  Math.min(1, confidence)
);

// =====================================================
// 11. Final output
// =====================================================

return [{
  json: {
    question,

    evidence_sufficient:
      flags.evidence_sufficient,

    confidence,

    decision:
      finalDecision,

    original_decision:
      originalDecision,

    needs_external_search:
      flags.needs_external_search,

    needs_human_review:
      flags.needs_human_review,

    reason:
      finalReason,

    supported_points:
      supportedPoints,

    missing_points:
      missingPoints,

    recommended_evidence_indexes:
      recommendedIndexes,

    combined_evidence:
      selectedEvidence,

    all_retrieved_evidence:
      allEvidence,

    best_score:
      Number(retrievalData.best_score || 0),

    retrieved_count:
      Number(retrievalData.retrieved_count || 0),

    usable_count:
      Number(retrievalData.usable_count || 0),

    hadith_integrity_guard:
      hadithGuard
  }
}];

parameters.text:
=سؤال المدعو:
{{ $json.question }}

الأدلة المتاحة:
{{ JSON.stringify($json.combined_evidence || $json.evidence || []) }}

النقاط التي ثبت أن الأدلة تدعمها:
{{ JSON.stringify($json.supported_points || []) }}

النقاط غير المكتملة أو التي لا ينبغي تجاوز الأدلة فيها:
{{ JSON.stringify($json.missing_points || []) }}

اكتب إجابة عربية نهائية موجهة مباشرة إلى المدعو، اعتمادًا حصريًا على الأدلة المتاحة.

يجب أن تكون الإجابة جاهزة ليقوم الداعية بنسخها وإرسالها إلى المدعو كما هي، دون أي تعديل.

parameters.jsCode:
const item = $input.first().json;

// ==========================================
// 1) قراءة مخرجات Generate Grounded Answer
// ==========================================

let raw = item.output ?? item.text ?? '';

if (typeof raw === 'string') {
  raw = raw
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');
}

let parsed;

try {
  parsed =
    typeof raw === 'object'
      ? raw
      : JSON.parse(raw);
} catch (error) {
  throw new Error(
    'تعذر تحويل إجابة Generate Grounded Answer إلى JSON: ' +
    error.message
  );
}


// ==========================================
// 2) استرجاع بيانات السؤال والسائل والأدلة
// ==========================================

let sourceData = {};

try {
  sourceData =
    $('Prepare Grounded Answer Input').first().json;
} catch (error) {
  sourceData = {};
}


// ==========================================
// 3) تنظيف وتوحيد المصادر المستخدمة
// ==========================================

const sourcesUsed = Array.isArray(parsed.sources_used)
  ? parsed.sources_used
      .filter(source => source && typeof source === 'object')
      .map(source => {

        let sourceType = String(
          source.source_type ?? ''
        )
          .trim()
          .toLowerCase();

        if (
          !['book', 'web', 'turath'].includes(sourceType)
        ) {
          sourceType = '';
        }

        return {
          source_type: sourceType,

          title:
            String(source.title ?? '').trim(),

          author:
            String(source.author ?? '').trim(),

          page:
            String(source.page ?? '').trim(),

          url:
            String(
              source.url ??
              source.source_url ??
              ''
            ).trim()
        };
      })
      // لا نحتفظ بمصدر فارغ تمامًا
      .filter(source =>
        source.title ||
        source.author ||
        source.page ||
        source.url
      )
  : [];


// ==========================================
// 4) إخراج البيانات كاملة للمرحلة التالية
// ==========================================

return [{
  json: {

    // بيانات السؤال والسائل
    question:
      sourceData.question ??
      item.question ??
      '',

    chat_id:
      sourceData.chat_id ??
      sourceData.requester_chat_id ??
      null,

    message_id:
      sourceData.message_id ??
      sourceData.requester_message_id ??
      null,

    user_id:
      sourceData.user_id ??
      null,

    target_language:
      sourceData.target_language ??
      'ti',


    // الأدلة
    combined_evidence:
      Array.isArray(sourceData.combined_evidence)
        ? sourceData.combined_evidence
        : Array.isArray(sourceData.evidence)
          ? sourceData.evidence
          : [],

    supported_points:
      Array.isArray(sourceData.supported_points)
        ? sourceData.supported_points
        : [],

    missing_points:
      Array.isArray(sourceData.missing_points)
        ? sourceData.missing_points
        : [],


    // الإجابة العربية الموجهة مباشرة للمدعو
    answer_ar:
      String(parsed.answer_ar ?? '').trim(),

    // المصادر المستخدمة فعليًا
    sources_used:
      sourcesUsed,

    grounded:
      parsed.grounded === true,


    // حالة الأدلة
    evidence_sufficient:
      sourceData.evidence_sufficient ??
      true,

    confidence:
      sourceData.confidence ??
      null,

    decision:
      sourceData.decision ??
      'SUPPORTED',


    // عدد محاولات تصحيح الإجابة
    answer_revision_attempt:
      Number(
        sourceData.answer_revision_attempt ?? 0
      ),


    // جاهزية الإجابة للتحقق
    ready_for_verification: true
  }
}];

const item = $input.first().json;

// ==========================================
// 1) قراءة نتيجة Answer Verification
// ==========================================

let raw = item.output ?? item.text ?? '';

if (typeof raw === 'string') {
  raw = raw
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');
}

let parsed;

try {
  parsed =
    typeof raw === 'object'
      ? raw
      : JSON.parse(raw);
} catch (error) {
  parsed = {
    verification: 'NEEDS_HUMAN_REVIEW',
    confidence: 0,
    reason: 'تعذر تحليل نتيجة التحقق.',
    unsupported_claims: [],
    required_corrections: []
  };
}


// ==========================================
// 2) تحديد مصدر الإجابة التي تم التحقق منها
// ==========================================

let sourceData = {};

// نحاول أولاً معرفة هل هذه جولة تحقق
// بعد تصحيح الإجابة
try {
  const revised =
    $('Store Revised Answer Context').first().json;

  if (
    revised &&
    revised.is_revised_answer === true &&
    Number(revised.answer_revision_attempt ?? 0) > 0
  ) {
    sourceData = revised;
  }
} catch (error) {
  // العقدة لم تعمل في هذا التنفيذ
}


// إذا لم تكن إجابة مصححة، نستخدم الإجابة الأصلية
if (!sourceData.answer_ar) {
  try {
    sourceData =
      $('Parse Grounded Answer').first().json;
  } catch (error) {
    sourceData = {};
  }
}


// ==========================================
// 3) تنظيف قرار التحقق
// ==========================================

const allowed = [
  'PASS',
  'REVISE',
  'NEEDS_HUMAN_REVIEW'
];

let verification =
  String(
    parsed.verification ??
    parsed.action ??
    'NEEDS_HUMAN_REVIEW'
  )
  .trim()
  .toUpperCase();

if (!allowed.includes(verification)) {
  verification = 'NEEDS_HUMAN_REVIEW';
}


// ==========================================
// 4) إخراج السياق + نتيجة التحقق
// ==========================================

return [{
  json: {

    ...sourceData,

    verification,

    verification_confidence:
      Number(parsed.confidence ?? 0),

    verification_reason:
      parsed.reason ?? '',

    unsupported_claims:
      Array.isArray(parsed.unsupported_claims)
        ? parsed.unsupported_claims
        : [],

    required_corrections:
      Array.isArray(parsed.required_corrections)
        ? parsed.required_corrections
        : [],

    answer_verified:
      verification === 'PASS',

    ready_for_translation:
      verification === 'PASS'
  }
}];

