parameters.jsCode:
const item = $input.first().json;

// ==========================================
// 1) قراءة نتيجة فحص الترجمة الحالية
// ==========================================

let raw = item.output ?? item.text ?? '';

if (typeof raw === 'string') {
  raw = raw
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');
}

let parsed;

try {
  parsed =
    typeof raw === 'object'
      ? raw
      : JSON.parse(raw);
} catch (error) {
  parsed = {
    translation_verified: false,
    confidence: 0,
    action: 'NEEDS_HUMAN_REVIEW',
    meaning_issues: [],
    omissions: [],
    additions: [],
    terminology_issues: [],
    citation_issues: [],
    reason: 'تعذر تحليل نتيجة التحقق من الترجمة.'
  };
}


// ==========================================
// 2) تحديد أي ترجمة تم التحقق منها
// ==========================================

let sourceData = {};
let verificationStage = 'INITIAL';

// إذا كانت عقدة التحقق من الترجمة المعدلة قد عملت
// في هذا المسار، نأخذ بيانات الترجمة المعدلة.
try {
  const revisedVerification =
    $('Verify Revised Tigrinya Translation').first().json;

  const revisedSource =
    $('Prepare Revised Translation Verification').first().json;

  if (
    revisedVerification &&
    revisedSource &&
    revisedSource.is_revised_translation === true &&
    Number(revisedSource.translation_attempt ?? 0) >= 2
  ) {
    sourceData = revisedSource;
    verificationStage = 'REVISED';
  }
} catch (error) {
  // المسار المعدل لم يعمل في هذا التنفيذ
}


// إذا لم يكن المسار المعدل هو المستخدم،
// نأخذ بيانات الترجمة الأولى.
if (!sourceData.answer_ti) {
  try {
    sourceData =
      $('Prepare Translation Verification').first().json;

    verificationStage = 'INITIAL';
  } catch (error) {
    sourceData = {};
  }
}


// ==========================================
// 3) تنظيف قرار المدقق
// ==========================================

const allowed = [
  'PASS',
  'REVISE',
  'NEEDS_HUMAN_REVIEW'
];

let action = String(
  parsed.action ?? 'NEEDS_HUMAN_REVIEW'
)
  .trim()
  .toUpperCase();

if (!allowed.includes(action)) {
  action = 'NEEDS_HUMAN_REVIEW';
}


// ==========================================
// 4) قاعدة الأمان للمحاولة الثانية
// ==========================================

// إذا فشلت الترجمة بعد المحاولة الثانية،
// لا نسمح بمحاولة آلية ثالثة.
// نحولها مباشرة إلى المراجع البشري.

const translationAttempt =
  Number(sourceData.translation_attempt ?? 1);

if (
  translationAttempt >= 2 &&
  action !== 'PASS'
) {
  action = 'NEEDS_HUMAN_REVIEW';
}


// ==========================================
// 5) إخراج السياق + نتيجة التحقق
// ==========================================

return [{
  json: {

    ...sourceData,

    translation_attempt:
      translationAttempt,

    verification_stage:
      verificationStage,

    translation_verified:
      parsed.translation_verified === true &&
      action === 'PASS',

    translation_confidence:
      Number(parsed.confidence ?? 0),

    action,

    translation_reason:
      parsed.reason ?? '',

    meaning_issues:
      Array.isArray(parsed.meaning_issues)
        ? parsed.meaning_issues
        : [],

    omissions:
      Array.isArray(parsed.omissions)
        ? parsed.omissions
        : [],

    additions:
      Array.isArray(parsed.additions)
        ? parsed.additions
        : [],

    terminology_issues:
      Array.isArray(parsed.terminology_issues)
        ? parsed.terminology_issues
        : [],

    citation_issues:
      Array.isArray(parsed.citation_issues)
        ? parsed.citation_issues
        : [],

    ready_for_final_output:
      action === 'PASS' &&
      parsed.translation_verified === true
  }
}];

const data = $input.first().json;


// ==========================================
// 1) التأكد من اعتماد الترجمة
// ==========================================

const isApproved =
  data.action === 'PASS' &&
  data.translation_verified === true;

if (!isApproved) {
  throw new Error(
    'لا يمكن تجهيز الإجابة النهائية لأن الترجمة لم تعتمد بعد.'
  );
}


// ==========================================
// 2) التأكد من وجود العربية والتغرينية
// ==========================================

const answerAr =
  String(data.answer_ar ?? '').trim();

const answerTi =
  String(data.answer_ti ?? '').trim();

if (!answerAr) {
  throw new Error(
    'الإجابة العربية النهائية غير موجودة.'
  );
}

if (!answerTi) {
  throw new Error(
    'الترجمة التغرينية النهائية غير موجودة.'
  );
}


// ==========================================
// 3) تحديد Chat ID للداعية
// ==========================================

const chatId =
  data.chat_id ??
  data.requester_chat_id ??
  null;

if (!chatId) {
  throw new Error(
    'لم يتم العثور على Chat ID الخاص بالداعية.'
  );
}


// ==========================================
// 4) تحديد مصدر الأدلة
// ==========================================

const evidenceSource =
  String(
    data.evidence_source ??
    'AUTOMATED_EVIDENCE'
  ).trim();


// ==========================================
// 5) تنظيف المصادر
// ==========================================

const sources =
  Array.isArray(data.sources_used)
    ? data.sources_used
        .filter(source =>
          source &&
          typeof source === 'object'
        )
        .map(source => ({
          source_type:
            String(
              source.source_type ?? ''
            ).trim(),

          title:
            String(
              source.title ?? ''
            ).trim(),

          author:
            String(
              source.author ?? ''
            ).trim(),

          page:
            String(
              source.page ??
              source.pages ??
              ''
            ).trim(),

          url:
            String(
              source.url ??
              source.source_url ??
              ''
            ).trim()
        }))
        .filter(source =>
          source.title ||
          source.author ||
          source.page ||
          source.url
        )
    : [];


// ==========================================
// 6) بناء قسم المصادر المخصص للداعية
// ==========================================

let sourcesText = '';


// ------------------------------------------
// الحالة الأولى:
// توجد مصادر فعلية
// ------------------------------------------

if (sources.length > 0) {

  sourcesText = sources
    .map((source, index) => {

      const lines = [];

      // رقم المصدر + الاسم
      if (source.title) {
        lines.push(
          `${index + 1}. ${source.title}`
        );
      } else {
        lines.push(
          `${index + 1}. مصدر`
        );
      }

      // المؤلف
      if (source.author) {
        lines.push(
          `المؤلف: ${source.author}`
        );
      }

      // الصفحة
      if (source.page) {
        lines.push(
          `الصفحة: ${source.page}`
        );
      }

      // الرابط
      if (source.url) {
        lines.push(
          `الرابط: ${source.url}`
        );
      }

      return lines.join('\n');

    })
    .join('\n\n');


// ------------------------------------------
// الحالة الثانية:
// الإجابة معتمدة من مراجعة بشرية
// ولا توجد مصادر مسجلة
// ------------------------------------------

} else if (
  evidenceSource === 'HUMAN_REVIEW' ||
  data.human_review_grounded === true ||
  data.translation_review_status === 'HUMAN_APPROVED'
) {

  sourcesText =
    'المصدر: مراجعة بشرية من المختص.';


// ------------------------------------------
// الحالة الثالثة:
// لا توجد بيانات مرجعية
// ------------------------------------------

} else {

  sourcesText =
    'لم تتوفر بيانات مرجعية كافية للعرض.';
}


// ==========================================
// 7) بناء الرسالة النهائية
// ==========================================

const finalAnswer =
`🇸🇦 الإجابة باللغة العربية

${answerAr}


🇪🇷 الإجابة باللغة التغرينية

${answerTi}


📚 المصادر والمراجع للتحقق

${sourcesText}`;


// ==========================================
// 8) إخراج البيانات النهائية
// ==========================================

return [{
  json: {

    question:
      data.question ?? '',

    chat_id:
      String(chatId),

    message_id:
      data.message_id ??
      data.requester_message_id ??
      null,

    user_id:
      data.user_id ??
      null,

    target_language:
      data.target_language ?? 'ti',


    // النصوص منفصلة
    answer_ar:
      answerAr,

    answer_ti:
      answerTi,


    // المصادر
    sources_used:
      sources,

    sources_display:
      sourcesText,


    // الرسالة النهائية الكاملة
    final_answer:
      finalAnswer,


    // بيانات التحقق من الترجمة
    translation_verified:
      true,

    translation_confidence:
      Number(
        data.translation_confidence ?? 1
      ),

    translation_attempt:
      Number(
        data.translation_attempt ?? 1
      ),

    translation_reason:
      data.translation_reason ?? '',


    // الحفاظ على المصدر الحقيقي للأدلة
    evidence_source:
      evidenceSource,


    // بيانات المراجعة البشرية إن وجدت
    human_review_grounded:
      data.human_review_grounded === true,

    translation_review_id:
      data.translation_review_id ?? null,

    translation_review_status:
      data.translation_review_status ?? null,


    // السماح بالإرسال
    ready_to_send:
      true
  }
}];

const data = $input.first().json;

// ==========================================
// 1) التحقق من جاهزية الإجابة للإرسال
// ==========================================

if (data.ready_to_send !== true) {
  throw new Error(
    'الإجابة ليست جاهزة للإرسال إلى Telegram.'
  );
}

// الرسالة النهائية:
// العربية + التغرينية + المصادر
const text = String(data.final_answer ?? '').trim();

if (!text) {
  throw new Error(
    'لا توجد رسالة نهائية لإرسالها إلى Telegram.'
  );
}

if (!data.chat_id) {
  throw new Error(
    'Chat ID الخاص بالداعية غير موجود.'
  );
}


// ==========================================
// 2) الحد الآمن لطول رسالة Telegram
// ==========================================

const MAX_LENGTH = 3800;


// ==========================================
// 3) إذا كانت الرسالة قصيرة
// ==========================================

if (text.length <= MAX_LENGTH) {
  return [{
    json: {
      ...data,

      telegram_text: text,

      part: 1,
      total_parts: 1
    }
  }];
}


// ==========================================
// 4) تقسيم النص مع الحفاظ على الفقرات
// ==========================================

const paragraphs = text.split(/\n{2,}/);

const chunks = [];
let current = '';

for (const paragraph of paragraphs) {

  const p = paragraph.trim();

  if (!p) continue;


  // ------------------------------------------
  // إذا كانت الفقرة نفسها أطول من الحد
  // ------------------------------------------

  if (p.length > MAX_LENGTH) {

    // حفظ النص المتراكم أولًا
    if (current.trim()) {
      chunks.push(current.trim());
      current = '';
    }

    const words = p.split(/\s+/);
    let longPart = '';

    for (const word of words) {

      const candidate =
        longPart
          ? `${longPart} ${word}`
          : word;

      if (candidate.length > MAX_LENGTH) {

        if (longPart.trim()) {
          chunks.push(longPart.trim());
        }

        longPart = word;

      } else {

        longPart = candidate;
      }
    }

    if (longPart.trim()) {
      current = longPart.trim();
    }

    continue;
  }


  // ------------------------------------------
  // محاولة إضافة الفقرة إلى الجزء الحالي
  // ------------------------------------------

  const candidate =
    current
      ? `${current}\n\n${p}`
      : p;

  if (candidate.length > MAX_LENGTH) {

    if (current.trim()) {
      chunks.push(current.trim());
    }

    current = p;

  } else {

    current = candidate;
  }
}


// ==========================================
// 5) إضافة آخر جزء
// ==========================================

if (current.trim()) {
  chunks.push(current.trim());
}


// ==========================================
// 6) إخراج كل جزء كـ Item مستقل
// ==========================================

const totalParts = chunks.length;

return chunks.map((chunk, index) => ({
  json: {
    ...data,

    telegram_text: chunk,

    part: index + 1,

    total_parts: totalParts
  }
}));

// جميع الصفوف القادمة من Google Sheet
const rows = $input.all();

// استرجاع بيانات السؤال الأصلية مباشرة من بداية الـ Workflow
let incoming = {};

try {
  incoming = $('Prepare Incoming Question').first().json;
} catch (error) {
  incoming = {};
}

// تجهيز قائمة المصادر المعتمدة
const sources = rows
  .map(item => ({
    row_number: item.json.row_number ?? '',
    category: String(item.json['المجال'] ?? '').trim(),
    approved_content: String(
      item.json['المحتوى المعتمد'] ?? ''
    ).trim(),
    usage_rule: String(
      item.json['قاعدة الاستخدام'] ?? ''
    ).trim()
  }))
  .filter(source =>
    source.approved_content ||
    source.category ||
    source.usage_rule
  );

// التحقق من وجود السؤال
const question = String(
  incoming.question ?? ''
).trim();

if (!question) {
  throw new Error(
    'لم يتم العثور على السؤال في Prepare Incoming Question.'
  );
}

// إخراج البيانات للعقدة التالية
return [{
  json: {
    question: question,

    chat_id: incoming.chat_id ?? null,
    message_id: incoming.message_id ?? null,
    user_id: incoming.user_id ?? null,

    target_language:
      incoming.target_language ?? 'ti',

    approved_sources: sources,
    approved_sources_count: sources.length
  }
}];

