parameters.jsCode:
const rerank = $input.first().json;

// ---------------------------------
// البيانات الأصلية بعد التحقق البرمجي
// ---------------------------------

let sourceData = {};

try {
  sourceData =
    $('Validate Approved Search Results').first().json;
} catch (error) {
  sourceData = {};
}

// ---------------------------------
// النتائج الأصلية الموثقة
// ---------------------------------

const originalResults =
  Array.isArray(sourceData.external_evidence)
    ? sourceData.external_evidence
    : [];

// ---------------------------------
// نتائج Cohere Rerank
// ---------------------------------

const reranked =
  Array.isArray(rerank.results)
    ? rerank.results
    : [];

// ---------------------------------
// إعادة ربط نتيجة Cohere بالمصدر الأصلي
// ---------------------------------

const externalEvidence = reranked
  .map((result, rank) => {

    const index =
      Number(result.index);

    if (
      !Number.isInteger(index) ||
      index < 0 ||
      index >= originalResults.length
    ) {
      return null;
    }

    const original =
      originalResults[index];

    if (!original) {
      return null;
    }

    const sourceUrl = String(
      original.source_url ??
      original.url ??
      ''
    ).trim();

    return {

      source_layer:
        'APPROVED_EXTERNAL_SOURCE',

      source_type:
        'web',

      rank:
        rank + 1,

      relevance_score:
        Number(
          result.relevance_score ?? 0
        ),

      title:
        String(
          original.title ?? ''
        ).trim(),

      content:
        String(
          original.content ?? ''
        ).trim(),

      source_url:
        sourceUrl,

      url:
        sourceUrl,

      source_domain:
        String(
          original.source_domain ?? ''
        ).trim(),

      source_verified:
        true
    };
  })
  .filter(
    evidence =>
      evidence &&
      evidence.content &&
      evidence.source_url
  );

// ---------------------------------
// أفضل درجة Rerank
// ---------------------------------

const bestExternalScore =
  externalEvidence.length > 0
    ? Math.max(
        ...externalEvidence.map(
          evidence =>
            Number(
              evidence.relevance_score ?? 0
            )
        )
      )
    : 0;

// ---------------------------------
// الإخراج الموحد
// ---------------------------------

return [{
  json: {

    question:
      sourceData.question ?? '',

    chat_id:
      sourceData.chat_id ?? null,

    message_id:
      sourceData.message_id ?? null,

    user_id:
      sourceData.user_id ?? null,

    target_language:
      sourceData.target_language ?? 'ti',

    search_intent:
      sourceData.search_intent ?? '',

    external_evidence:
      externalEvidence,

    external_evidence_count:
      externalEvidence.length,

    best_external_score:
      bestExternalScore,

    approved_domains:
      Array.isArray(
        sourceData.approved_domains
      )
        ? sourceData.approved_domains
        : [],

    approved_urls:
      Array.isArray(
        sourceData.approved_urls
      )
        ? sourceData.approved_urls
        : [],

    selected_sources:
      Array.isArray(
        sourceData.selected_sources
      )
        ? sourceData.selected_sources
        : [],

    evidence_source:
      'APPROVED_EXTERNAL_SEARCH',

    source_validation_passed:
      externalEvidence.length > 0
  }
}];

const externalData = $input.first().json;

// ---------------------------------
// الأدلة الخارجية المعتمدة
// القادمة من Build External Evidence
// ---------------------------------

const externalEvidence =
  Array.isArray(externalData.external_evidence)
    ? externalData.external_evidence
    : [];

// ---------------------------------
// التحقق من وجود أدلة فعلية
// ---------------------------------

if (externalEvidence.length === 0) {
  throw new Error(
    'لم تصل أدلة خارجية صالحة من Build External Evidence.'
  );
}

// ---------------------------------
// إخراج موحد لـ Final Evidence Judge
// ---------------------------------

return [{
  json: {

    question:
      externalData.question ?? '',

    chat_id:
      externalData.chat_id ?? null,

    message_id:
      externalData.message_id ?? null,

    user_id:
      externalData.user_id ?? null,

    target_language:
      externalData.target_language ?? 'ti',

    search_intent:
      externalData.search_intent ?? '',

    // الأدلة التي سيقيّمها Final Evidence Judge
    combined_evidence:
      externalEvidence,

    evidence:
      externalEvidence,

    evidence_count:
      externalEvidence.length,

    external_evidence:
      externalEvidence,

    external_evidence_count:
      externalEvidence.length,

    best_external_score:
      externalData.best_external_score ?? 0,

    approved_domains:
      Array.isArray(externalData.approved_domains)
        ? externalData.approved_domains
        : [],

    approved_urls:
      Array.isArray(externalData.approved_urls)
        ? externalData.approved_urls
        : [],

    selected_sources:
      Array.isArray(externalData.selected_sources)
        ? externalData.selected_sources
        : [],

    evidence_layers: [
      'APPROVED_EXTERNAL_SOURCE'
    ],

    external_search_completed: true,

    evidence_source:
      'APPROVED_EXTERNAL_SEARCH'
  }
}];

const item = $input.first().json;

// ---------------------------------
// قراءة مخرجات Final Evidence Judge
// ---------------------------------

let raw =
  item.text ??
  item.output ??
  '';

if (typeof raw === 'string') {
  raw = raw
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');
}

// ---------------------------------
// تحليل قرار المقيم
// ---------------------------------

let decision;

try {

  decision =
    typeof raw === 'object'
      ? raw
      : JSON.parse(raw);

} catch (error) {

  // Fail-safe:
  // إذا تعذر فهم قرار المقيم النهائي
  // لا نسمح بتوليد إجابة آلية.

  decision = {
    evidence_sufficient: false,
    confidence: 0,
    decision: 'NEEDS_HUMAN_REVIEW',
    needs_human_review: true,

    reason:
      'تعذر قراءة قرار التقييم النهائي للأدلة الخارجية.',

    supported_points: [],
    missing_points: []
  };
}

// ---------------------------------
// القرارات المسموح بها
// ---------------------------------

const allowedDecisions = [
  'SUPPORTED',
  'NEEDS_HUMAN_REVIEW'
];

let finalDecision =
  String(
    decision.decision ?? ''
  )
    .trim()
    .toUpperCase();

// ---------------------------------
// حماية من أي قرار غير معروف
// ---------------------------------

if (
  !allowedDecisions.includes(
    finalDecision
  )
) {

  finalDecision =
    'NEEDS_HUMAN_REVIEW';

  decision.evidence_sufficient =
    false;

  decision.needs_human_review =
    true;

  decision.reason =
    decision.reason ||
    'أعاد المقيم النهائي قرارًا غير معتمد.';
}

// ---------------------------------
// فرض الاتساق المنطقي
// ---------------------------------

const evidenceSufficient =
  finalDecision === 'SUPPORTED';

const needsHumanReview =
  finalDecision ===
  'NEEDS_HUMAN_REVIEW';

// ---------------------------------
// استرجاع الأدلة الخارجية الأصلية
// من العقدة الفعلية الحالية
// ---------------------------------

let evidenceData = {};

try {

  evidenceData =
    $('Build External Evidence')
      .first()
      .json;

} catch (error) {

  evidenceData = {};
}

// ---------------------------------
// الأدلة الخارجية
// ---------------------------------

const externalEvidence =
  Array.isArray(
    evidenceData.external_evidence
  )
    ? evidenceData.external_evidence
    : [];

// ---------------------------------
// إخراج موحد للمسار التالي
// ---------------------------------

return [{
  json: {

    question:
      evidenceData.question ?? '',

    chat_id:
      evidenceData.chat_id ?? null,

    message_id:
      evidenceData.message_id ?? null,

    user_id:
      evidenceData.user_id ?? null,

    target_language:
      evidenceData.target_language ?? 'ti',

    search_intent:
      evidenceData.search_intent ?? '',

    // نحول الأدلة الخارجية إلى الاسم
    // الذي يتوقعه مسار توليد الإجابة
    combined_evidence:
      externalEvidence,

    external_evidence:
      externalEvidence,

    external_evidence_count:
      externalEvidence.length,

    best_external_score:
      Number(
        evidenceData.best_external_score ??
        0
      ),

    approved_domains:
      Array.isArray(
        evidenceData.approved_domains
      )
        ? evidenceData.approved_domains
        : [],

    approved_urls:
      Array.isArray(
        evidenceData.approved_urls
      )
        ? evidenceData.approved_urls
        : [],

    selected_sources:
      Array.isArray(
        evidenceData.selected_sources
      )
        ? evidenceData.selected_sources
        : [],

    evidence_source:
      'APPROVED_EXTERNAL_SEARCH',

    evidence_sufficient:
      evidenceSufficient,

    confidence:
      Number(
        decision.confidence ?? 0
      ),

    decision:
      finalDecision,

    needs_human_review:
      needsHumanReview,

    decision_reason:
      String(
        decision.reason ?? ''
      ).trim(),

    supported_points:
      Array.isArray(
        decision.supported_points
      )
        ? decision.supported_points
        : [],

    missing_points:
      Array.isArray(
        decision.missing_points
      )
        ? decision.missing_points
        : [],

    final_evidence_evaluated:
      true
  }
}];

/**
 * Bayyinah | Prepare Revised Grounded Answer
 *
 * Supports:
 * - Citation Verification -> REVISE
 * - Answer Verification -> REVISE
 *
 * Fix:
 * Restore citations from verified evidence metadata.
 * Never invent new books, pages or URLs.
 * Never blindly cite all retrieved pages.
 */

const input = $input.first().json;

// =====================================================
// 1. Parse revised answer
// =====================================================

let raw = input.output ?? input.text ?? "";

if (typeof raw === "string") {
  raw = raw
    .trim()
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "");
}

let revised;

try {
  revised =
    typeof raw === "string"
      ? JSON.parse(raw)
      : raw;
} catch (error) {
  throw new Error(
    "تعذر قراءة الإجابة المصححة: " + error.message
  );
}

if (!revised || typeof revised !== "object") {
  throw new Error("مخرجات المصحح ليست JSON صالحًا.");
}

const answer = String(
  revised.answer_ar ?? ""
).trim();

if (!answer) {
  throw new Error(
    "الإجابة المصححة لا تحتوي على answer_ar."
  );
}

// =====================================================
// 2. Retrieve previous verification context
// =====================================================

let previous = {};

try {
  previous =
    $("Check Answer Revision Attempt")
      .first()
      .json || {};
} catch (error) {
  throw new Error(
    "تعذر استرجاع سياق التصحيح السابق."
  );
}

const evidence = Array.isArray(
  previous.combined_evidence
)
  ? previous.combined_evidence
  : [];

const claims = Array.isArray(
  previous.claim_verifications
)
  ? previous.claim_verifications
  : [];

// =====================================================
// 3. Helpers
// =====================================================

function clean(value) {
  return String(value ?? "").trim();
}

function normalizeText(value) {
  return clean(value)
    .normalize("NFKC")
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function normalizeDigits(value) {
  return clean(value)
    .replace(/[٠-٩]/g, char =>
      String(char.charCodeAt(0) - 1632)
    )
    .replace(/[۰-۹]/g, char =>
      String(char.charCodeAt(0) - 1776)
    );
}

function pageNumbers(value) {
  const matches =
    normalizeDigits(value).match(/\d+/g) || [];

  return [...new Set(matches)];
}

function evidencePages(item) {
  if (!item || typeof item !== "object") {
    return [];
  }

  const printed = Array.isArray(
    item.printed_pages
  )
    ? item.printed_pages
    : [];

  const pdf = Array.isArray(item.pdf_pages)
    ? item.pdf_pages
    : [];

  const rawPages =
    printed.length > 0
      ? printed
      : pdf.length > 0
        ? pdf
        : [
            item.page_start,
            item.page_end
          ];

  return [...new Set(
    rawPages
      .filter(value =>
        value !== null &&
        value !== undefined &&
        clean(value) !== ""
      )
      .flatMap(pageNumbers)
  )];
}

function normalizeSourceType(item) {
  const type = normalizeText(
    item.source_type
  );

  if (["book", "web", "turath"].includes(type)) {
    return type;
  }

  return clean(
    item.source_url ?? item.url
  )
    ? "web"
    : "book";
}

function sourceFromEvidence(item, page = "") {
  if (!item || typeof item !== "object") {
    return null;
  }

  const type = normalizeSourceType(item);

  const title = clean(
    item.source_title ??
    item.book_title ??
    item.source_name ??
    item.title ??
    ""
  );

  const author = clean(
    item.author ??
    item.book_author ??
    item.source_author ??
    ""
  );

  const url = clean(
    item.source_url ??
    item.url ??
    ""
  );

  if (type === "web" && !url) {
    return null;
  }

  if (type !== "web" && !title) {
    return null;
  }

  return {
    source_type: type,
    title,
    author,
    page: type === "web" ? "" : clean(page),
    url: type === "web" ? url : url
  };
}

function sourceKey(source) {
  return [
    source.source_type,
    source.title,
    source.author,
    source.page,
    source.url
  ]
    .map(normalizeText)
    .join("||");
}

const finalSources = [];
const seen = new Set();

function addSource(source) {
  if (!source) return;

  const key = sourceKey(source);

  if (seen.has(key)) return;

  seen.add(key);
  finalSources.push(source);
}

// =====================================================
// 4. Restore citations from claim verification
//
// Only supported claims.
// Only evidence indexes actually cited.
// Only pages present in evidence metadata.
// =====================================================

let verifiedEvidenceFound = false;

for (const claim of claims) {
  if (claim.supported !== true) {
    continue;
  }

  const indexes = Array.isArray(
    claim.evidence_indexes
  )
    ? claim.evidence_indexes
    : [];

  const claimedPages = Array.isArray(
    claim.source_pages
  )
    ? claim.source_pages.flatMap(pageNumbers)
    : [];

  for (const rawIndex of indexes) {
    const index = Number(rawIndex);

    if (
      !Number.isInteger(index) ||
      index < 0 ||
      index >= evidence.length
    ) {
      continue;
    }

    const item = evidence[index];

    const availablePages = evidencePages(item);

    const allowedPages =
      claimedPages.length > 0
        ? availablePages.filter(page =>
            claimedPages.includes(page)
          )
        : availablePages;

    // Reject invalid page references.
    if (
      claimedPages.length > 0 &&
      availablePages.length > 0 &&
      allowedPages.length === 0
    ) {
      continue;
    }

    verifiedEvidenceFound = true;

    if (allowedPages.length === 0) {
      addSource(sourceFromEvidence(item));
      continue;
    }

    for (const page of allowedPages) {
      addSource(
        sourceFromEvidence(item, page)
      );
    }
  }
}

// =====================================================
// 5. Fallback when no claim-level references exist
//
// Preserve only sources matching actual evidence.
// Never trust proposed metadata by itself.
// =====================================================

function validateProposedSource(proposed) {
  if (
    !proposed ||
    typeof proposed !== "object"
  ) {
    return;
  }

  const wantedTitle = normalizeText(
    proposed.title
  );

  const wantedUrl = clean(
    proposed.url ?? proposed.source_url
  );

  const wantedPages = pageNumbers(
    proposed.page
  );

  const wantedType = normalizeText(
    proposed.source_type
  );

  for (const item of evidence) {
    const canonical =
      sourceFromEvidence(item);

    if (!canonical) continue;

    if (
      wantedType &&
      wantedType !== canonical.source_type
    ) {
      continue;
    }

    if (
      wantedTitle &&
      wantedTitle !== normalizeText(
        canonical.title
      )
    ) {
      continue;
    }

    if (
      wantedUrl &&
      wantedUrl !== canonical.url
    ) {
      continue;
    }

    const availablePages =
      evidencePages(item);

    // A specified page must exist in the evidence.
    const matchingPages =
      wantedPages.length > 0
        ? availablePages.filter(page =>
            wantedPages.includes(page)
          )
        : [];

    if (canonical.source_type === "web") {
      if (
        wantedUrl &&
        wantedUrl === canonical.url
      ) {
        addSource(canonical);
      }

      continue;
    }

    for (const page of matchingPages) {
      addSource(
        sourceFromEvidence(item, page)
      );
    }
  }
}

const previousSources = Array.isArray(
  previous.sources_used
)
  ? previous.sources_used
  : [];

const proposedSources = Array.isArray(
  revised.sources_used
)
  ? revised.sources_used
  : [];

if (!verifiedEvidenceFound) {
  for (const source of [
    ...previousSources,
    ...proposedSources
  ]) {
    validateProposedSource(source);
  }
}

// =====================================================
// 6. Track rejected / unrelated proposed citations
// =====================================================

const blockedNewSources = [];

for (const proposed of proposedSources) {
  if (
    !proposed ||
    typeof proposed !== "object"
  ) {
    continue;
  }

  const title = normalizeText(
    proposed.title
  );

  const url = clean(
    proposed.url ?? proposed.source_url
  );

  const pages = pageNumbers(
    proposed.page
  );

  const matches = finalSources.filter(source => {
    if (
      title &&
      normalizeText(source.title) !== title
    ) {
      return false;
    }

    if (
      url &&
      source.url !== url
    ) {
      return false;
    }

    return true;
  });

  const acceptedPages = new Set(
    matches.flatMap(source =>
      pageNumbers(source.page)
    )
  );

  const valid =
    matches.length > 0 &&
    (
      pages.length === 0 ||
      pages.every(page =>
        acceptedPages.has(page)
      )
    );

  if (!valid) {
    blockedNewSources.push(proposed);
  }
}

// =====================================================
// 7. Revision metadata
// =====================================================

const revisionOrigin =
  previous.citation_verification === "REVISE"
    ? "CITATION_VERIFICATION"
    : previous.verification === "REVISE"
      ? "ANSWER_VERIFICATION"
      : "UNKNOWN";

const revisionReason =
  revisionOrigin === "CITATION_VERIFICATION"
    ? previous.citation_verification_reason
    : previous.verification_reason;

const revisionTrigger = {
  origin: revisionOrigin,

  verification:
    previous.verification ?? null,

  citation_verification:
    previous.citation_verification ?? null,

  reason:
    revisionReason ||
    previous.reason ||
    "",

  unsupported_claims:
    Array.isArray(previous.unsupported_claims)
      ? previous.unsupported_claims
      : [],

  required_corrections:
    Array.isArray(previous.required_corrections)
      ? previous.required_corrections
      : [],

  groundedness_score:
    previous.groundedness_score ?? null,

  citation_correctness_score:
    previous.citation_correctness_score ?? null
};

const previousAttempt = Number(
  previous.answer_revision_attempt ?? 0
);

const revisionAttempt =
  (Number.isFinite(previousAttempt)
    ? previousAttempt
    : 0) + 1;

// =====================================================
// 8. Output for fresh Citation Verification
//
// This node does NOT declare the answer verified.
// The next verification must check the revised text
// and every restored source again.
// =====================================================

return [{
  json: {
    ...previous,

    answer_ar: answer,

    sources_used: finalSources,

    blocked_new_sources: blockedNewSources,

    citation_recovery_method:
      verifiedEvidenceFound
        ? "VERIFIED_CLAIM_EVIDENCE"
        : "MATCHED_EXISTING_EVIDENCE",

    citation_recovery_count:
      finalSources.length,

    grounded: false,

    answer_revision_attempt:
      revisionAttempt,

    revision_origin:
      revisionOrigin,

    revision_trigger:
      revisionTrigger,

    verification: null,
    verification_confidence: null,
    verification_reason: "",

    citation_verification: null,
    citation_verification_confidence: null,
    citation_verification_reason: "",

    unsupported_claims: [],
    required_corrections: [],

    claim_verifications: [],
    citation_checks: [],

    groundedness_score: null,
    citation_correctness_score: null,

    answer_verified: false,
    ready_for_translation: false,
    ready_for_verification: true
  }
}];

const data = $input.first().json;

const reviewId =
  `TR-${data.chat_id || data.requester_chat_id || 'unknown'}-${Date.now()}`;

return [{
  json: {
    ...data,

    translation_review_id: reviewId,

    translation_review_status: 'WAITING_FOR_HUMAN',

    review_message:
`طلب مراجعة ترجمة تغرينية

رقم المراجعة:
${reviewId}

النص العربي الأصلي:
${data.answer_ar || ''}

الترجمة التغرينية الحالية:
${data.answer_ti || ''}

سبب الإحالة:
${data.translation_reason || 'تحتاج الترجمة إلى مراجعة بشرية.'}

المطلوب:
راجع الترجمة التغرينية وصححها فقط، دون إضافة معلومات جديدة.

ابدأ ردك برقم المراجعة:
${reviewId}

ثم ضع الترجمة التغرينية المصححة.`
  }
}];

const data = $input.first().json;

const text = String(data.message?.text || '').trim();

if (!text) {
  throw new Error('رسالة مراجع الترجمة فارغة.');
}

// السطر الأول يجب أن يحتوي رقم المراجعة TR-...
const lines = text.split(/\r?\n/);

const translationReviewId = lines[0].trim();

if (!translationReviewId.startsWith('TR-')) {
  throw new Error('رقم مراجعة الترجمة غير صحيح.');
}

// كل ما بعد السطر الأول هو الترجمة المصححة
const reviewedTranslation = lines
  .slice(1)
  .join('\n')
  .trim();

if (!reviewedTranslation) {
  throw new Error(
    'لم يتم العثور على الترجمة المصححة بعد رقم المراجعة.'
  );
}

return [{
  json: {
    translation_review_id: translationReviewId,

    reviewed_translation: reviewedTranslation,

    reviewer_chat_id:
      String(data.message?.chat?.id || ''),

    reviewer_user_id:
      String(data.message?.from?.id || ''),

    reviewer_message_id:
      String(data.message?.message_id || ''),

    reviewed_at:
      new Date().toISOString()
  }
}];

const updated = $input.first().json;

// ==========================================
// 1) بيانات رد المراجع
// ==========================================

const reviewResponse =
  $('Parse Translation Review Response').first().json;

// ==========================================
// 2) السجل الأصلي للمراجعة
// ==========================================

const originalCase =
  $('Find Translation Review Case').first().json;


// ==========================================
// 3) الترجمة التي اعتمدها المراجع
// ==========================================

const finalTranslation =
  String(
    reviewResponse.reviewed_translation ??
    updated.reviewed_translation ??
    ''
  ).trim();

if (!finalTranslation) {
  throw new Error(
    'لم يتم العثور على الترجمة التغرينية التي اعتمدها المراجع.'
  );
}


// ==========================================
// 4) Chat ID الأصلي
// ==========================================

const chatId =
  originalCase.requester_chat_id ??
  updated.requester_chat_id ??
  null;

if (!chatId) {
  throw new Error(
    'لم يتم العثور على Chat ID الخاص بالسائل الأصلي.'
  );
}


// ==========================================
// 5) استعادة المصادر الأصلية
// ==========================================

let sourcesUsed = [];

const rawSources =
  originalCase.sources_used_json ??
  updated.sources_used_json ??
  '[]';

try {

  if (Array.isArray(rawSources)) {

    sourcesUsed = rawSources;

  } else if (
    typeof rawSources === 'string' &&
    rawSources.trim()
  ) {

    const parsedSources =
      JSON.parse(rawSources);

    sourcesUsed =
      Array.isArray(parsedSources)
        ? parsedSources
        : [];
  }

} catch (error) {

  sourcesUsed = [];
}


// ==========================================
// 6) استعادة مصدر الأدلة الأصلي
// ==========================================

const evidenceSource =
  String(
    originalCase.evidence_source ??
    updated.evidence_source ??
    ''
  ).trim();


// ==========================================
// 7) هل سبقت الترجمة مراجعة علمية بشرية؟
// ==========================================

const humanReviewGrounded =
  originalCase.human_review_grounded === true ||
  updated.human_review_grounded === true;


// ==========================================
// 8) إخراج السياق الكامل بعد المراجعة البشرية
// ==========================================

return [{
  json: {

    question:
      originalCase.question ??
      updated.question ??
      '',

    chat_id:
      String(chatId),

    answer_ar:
      String(
        originalCase.answer_ar ??
        updated.answer_ar ??
        ''
      ).trim(),

    answer_ti:
      finalTranslation,

    sources_used:
      sourcesUsed,

    evidence_source:
      evidenceSource || 'UNKNOWN',

    human_review_grounded:
      humanReviewGrounded,

    translation_verified:
      true,

    translation_confidence:
      1,

    translation_attempt:
      Number(
        updated.translation_attempt ??
        2
      ),

    translation_reason:
      'تم اعتماد الترجمة بعد مراجعة بشرية.',

    translation_review_id:
      originalCase.translation_review_id ??
      reviewResponse.translation_review_id ??
      null,

    translation_review_status:
      'HUMAN_APPROVED',

    reviewer_user_id:
      reviewResponse.reviewer_user_id ??
      null,

    reviewer_message_id:
      reviewResponse.reviewer_message_id ??
      null,

    reviewed_at:
      reviewResponse.reviewed_at ??
      null,

    action:
      'PASS',

    ready_for_final_output:
      true
  }
}];

const data = $input.first().json;

// ==========================================
// 1) استرجاع بيانات السائل الأصلي من Telegram
// ==========================================

let incoming = {};

try {
  incoming =
    $('Prepare Incoming Question').first().json;
} catch (error) {
  incoming = {};
}


// ==========================================
// 2) استرجاع الأدلة المجمعة
// ==========================================

let evidenceData = {};

// أولاً نحاول أخذ البيانات الحالية
if (
  Array.isArray(data.combined_evidence) &&
  data.combined_evidence.length > 0
) {
  evidenceData = data;
}


// إذا لم توجد، نأخذها من Combine Evidence
if (
  !Array.isArray(evidenceData.combined_evidence) ||
  evidenceData.combined_evidence.length === 0
) {
  try {
    const combined =
      $('Combine Evidence').first().json;

    if (
      Array.isArray(combined.combined_evidence) &&
      combined.combined_evidence.length > 0
    ) {
      evidenceData = combined;
    }
  } catch (error) {
    // نكمل
  }
}


// إذا كان القرار بعد البحث الخارجي
// نستخدم Combine External Evidence
try {
  const external =
    $('Combine External Evidence').first().json;

  if (
    Array.isArray(external.combined_evidence) &&
    external.combined_evidence.length > 0
  ) {
    evidenceData = external;
  }
} catch (error) {
  // هذا طبيعي إذا لم يعمل البحث الخارجي
}


// ==========================================
// 3) تحديد الأدلة النهائية
// ==========================================

const combinedEvidence =
  Array.isArray(data.combined_evidence) &&
  data.combined_evidence.length > 0
    ? data.combined_evidence
    : Array.isArray(evidenceData.combined_evidence)
      ? evidenceData.combined_evidence
      : [];


// ==========================================
// 4) بيانات قرار Evidence Judge
// ==========================================

const supportedPoints =
  Array.isArray(data.supported_points)
    ? data.supported_points
    : [];

const missingPoints =
  Array.isArray(data.missing_points)
    ? data.missing_points
    : [];


// ==========================================
// 5) إخراج السياق الكامل
// ==========================================

return [{
  json: {

    // بيانات السائل
    question:
      data.question ??
      incoming.question ??
      '',

    chat_id:
      data.chat_id ??
      data.requester_chat_id ??
      incoming.chat_id ??
      null,

    message_id:
      data.message_id ??
      data.requester_message_id ??
      incoming.message_id ??
      null,

    user_id:
      data.user_id ??
      incoming.user_id ??
      null,

    target_language:
      data.target_language ??
      incoming.target_language ??
      'ti',

    // الأدلة
    combined_evidence:
      combinedEvidence,

    supported_points:
      supportedPoints,

    missing_points:
      missingPoints,

    // قرار كفاية الأدلة
    evidence_sufficient:
      data.evidence_sufficient ?? true,

    confidence:
      data.confidence ?? null,

    decision:
      data.decision ?? 'SUPPORTED',

    // التحكم في التصحيح
    answer_revision_attempt:
      Number(data.answer_revision_attempt ?? 0)
  }
}];

