// ==========================================================
// Bayyinah | Parse JSONL Chunks
// قراءة ملفات JSONL والتحقق منها مع حفظ هوية ملف Google Drive
// ==========================================================

const items = $input.all();

if (!items.length) {
  throw new Error('لم تصل أي ملفات JSONL من Google Drive.');
}

const output = [];

// الهوية الفريدة للـChunk:
// document_id + chunk_id
const seenChunkKeys = new Set();


// ==========================================================
// معالجة كل ملف JSONL
// ==========================================================

for (let fileIndex = 0; fileIndex < items.length; fileIndex++) {

  const item = items[fileIndex];


  // ========================================================
  // 1) التحقق من وجود الملف Binary
  // ========================================================

  if (!item.binary?.data) {
    throw new Error(
      `الملف رقم ${fileIndex + 1} لا يحتوي على binary property باسم "data".`
    );
  }


  // ========================================================
  // 2) استخراج هوية ملف Google Drive
  // ========================================================

  // نحاول أخذ file_id من البيانات القادمة مع الملف.
  // وإذا لم تكن موجودة بعد Download، نرجع إلى
  // Filter Already Processed Files حسب نفس ترتيب الملفات.

  const filteredFiles =
    $('Filter Already Processed Files').all();

  const driveFile =
    filteredFiles[fileIndex];

  const driveFileId =
    String(
      item.json?.id ||
      driveFile?.json?.id ||
      ''
    ).trim();

  if (!driveFileId) {
    throw new Error(
      `تعذر تحديد Google Drive file_id للملف رقم ${fileIndex + 1}.`
    );
  }


  // ========================================================
  // 3) اسم الملف
  // ========================================================

  const fileName =
    String(
      item.binary.data.fileName ||
      item.json?.name ||
      driveFile?.json?.name ||
      `file_${fileIndex + 1}.jsonl`
    ).trim();

  if (!fileName) {
    throw new Error(
      `تعذر تحديد اسم الملف رقم ${fileIndex + 1}.`
    );
  }

  if (!fileName.toLowerCase().endsWith('.jsonl')) {
    throw new Error(
      `الملف "${fileName}" ليس ملف JSONL.`
    );
  }


  // ========================================================
  // 4) قراءة محتوى الملف
  // ========================================================

  const buffer =
    await this.helpers.getBinaryDataBuffer(
      fileIndex,
      'data'
    );

  const content = buffer
    .toString('utf8')
    .replace(/^\uFEFF/, '')
    .trim();

  if (!content) {
    throw new Error(
      `ملف JSONL فارغ: ${fileName}`
    );
  }


  // ========================================================
  // 5) تقسيم JSONL إلى سجلات
  // ========================================================

  const lines = content
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);

  if (!lines.length) {
    throw new Error(
      `لم يتم العثور على سجلات داخل الملف: ${fileName}`
    );
  }


  // ========================================================
  // 6) قراءة وفحص كل Chunk
  // ========================================================

  for (
    let lineIndex = 0;
    lineIndex < lines.length;
    lineIndex++
  ) {

    let record;

    try {

      record = JSON.parse(lines[lineIndex]);

    } catch (error) {

      throw new Error(
        `JSON غير صالح في الملف "${fileName}" ` +
        `عند السطر ${lineIndex + 1}: ${error.message}`
      );
    }


    // ------------------------------------------------------
    // التحقق من أن السجل Object
    // ------------------------------------------------------

    if (
      !record ||
      typeof record !== 'object' ||
      Array.isArray(record)
    ) {

      throw new Error(
        `السجل في الملف "${fileName}" ` +
        `عند السطر ${lineIndex + 1} ` +
        `ليس JSON Object صالحًا.`
      );
    }


    // ======================================================
    // 7) Chunk ID
    // ======================================================

    const chunkId =
      String(record.id || '').trim();

    if (!chunkId) {

      throw new Error(
        `id مفقود في الملف "${fileName}" ` +
        `عند السطر ${lineIndex + 1}.`
      );
    }


    // ======================================================
    // 8) النص
    // ======================================================

    const text =
      String(record.text || '').trim();

    if (!text) {

      throw new Error(
        `text فارغ في Chunk "${chunkId}" ` +
        `داخل الملف "${fileName}".`
      );
    }


    // ======================================================
    // 9) Metadata
    // ======================================================

    if (
      !record.metadata ||
      typeof record.metadata !== 'object' ||
      Array.isArray(record.metadata)
    ) {

      throw new Error(
        `metadata مفقودة أو غير صالحة ` +
        `في Chunk "${chunkId}".`
      );
    }


    // ======================================================
    // 10) Document ID
    // ======================================================

    const documentId =
      String(
        record.metadata.document_id || ''
      ).trim();

    if (!documentId) {

      throw new Error(
        `metadata.document_id مفقود ` +
        `في Chunk "${chunkId}" ` +
        `داخل الملف "${fileName}".`
      );
    }


    // ======================================================
    // 11) Source Title
    // ======================================================

    const sourceTitle =
      String(
        record.metadata.source_title || ''
      ).trim();

    if (!sourceTitle) {

      throw new Error(
        `metadata.source_title مفقود ` +
        `في Chunk "${chunkId}" ` +
        `داخل الملف "${fileName}".`
      );
    }


    // ======================================================
    // 12) الهوية المركبة للـChunk
    // ======================================================

    const chunkKey =
      `${documentId}::${chunkId}`;


    // ======================================================
    // 13) منع التكرار
    // ======================================================

    if (seenChunkKeys.has(chunkKey)) {

      throw new Error(
        `Chunk مكرر داخل ملفات الإدخال: "${chunkKey}". ` +
        `الملف: "${fileName}"، ` +
        `السطر: ${lineIndex + 1}.`
      );
    }

    seenChunkKeys.add(chunkKey);


    // ======================================================
    // 14) القيم الافتراضية
    // ======================================================

    const sourceType =
      String(
        record.metadata.source_type || 'book'
      ).trim() || 'book';

    const language =
      String(
        record.metadata.language || 'ar'
      ).trim() || 'ar';


    // ======================================================
    // 15) إخراج Chunk
    // ======================================================

    output.push({

      json: {

        ...record,

        id:
          chunkId,

        text,

        metadata: {

          ...record.metadata,

          // ----------------------------------------------
          // هوية ملف Google Drive
          // ----------------------------------------------

          drive_file_id:
            driveFileId,

          drive_file_name:
            fileName,

          // ----------------------------------------------
          // هوية الكتاب
          // ----------------------------------------------

          document_id:
            documentId,

          source_title:
            sourceTitle,

          source_type:
            sourceType,

          language:
            language
        }
      }
    });
  }
}


// ==========================================================
// 16) التحقق النهائي
// ==========================================================

if (!output.length) {

  throw new Error(
    'لم يتم العثور على أي Chunks صالحة داخل ملفات JSONL.'
  );
}


// ==========================================================
// 17) التحقق من أن كل ملف جديد أنتج Chunks
// ==========================================================

const expectedFiles =
  $('Filter Already Processed Files').all();

const producedFileIds =
  new Set(
    output
      .map(item =>
        String(
          item.json?.metadata?.drive_file_id || ''
        ).trim()
      )
      .filter(Boolean)
  );

for (const file of expectedFiles) {

  const expectedFileId =
    String(file.json?.id || '').trim();

  const expectedFileName =
    String(file.json?.name || '').trim();

  if (
    expectedFileId &&
    !producedFileIds.has(expectedFileId)
  ) {

    throw new Error(
      `الملف "${expectedFileName}" لم ينتج أي Chunks صالحة. ` +
      `لن يستمر الإدخال حتى تتم مراجعة الملف.`
    );
  }
}


return output;

// =====================================================
// Bayyinah | Filter Already Processed Files
// استبعاد ملفات المعرفة التي سبق إدخالها
// =====================================================

// الملفات الأصلية الموجودة في مجلد Google Drive
const driveFiles = $('Search files and folders').all();

// السجلات الموجودة في processed_knowledge_files
// وهي المدخل الحالي لهذه العقدة
const processedRows = $input.all();

// إنشاء قائمة بمعرّفات الملفات التي سبق نجاح معالجتها
const processedFileIds = new Set(
  processedRows
    .filter(item => String(item.json.status || '').trim() === 'success')
    .map(item => String(item.json.file_id || '').trim())
    .filter(Boolean)
);

// الاحتفاظ فقط بالملفات التي لم يسبق معالجتها
const newFiles = driveFiles.filter(item => {
  const fileId = String(item.json.id || '').trim();

  if (!fileId) {
    throw new Error(
      'تم العثور على ملف من Google Drive بدون id.'
    );
  }

  return !processedFileIds.has(fileId);
});

// إخراج الملفات الجديدة فقط
return newFiles.map(item => ({
  json: {
    id: String(item.json.id || '').trim(),
    name: String(item.json.name || '').trim(),
  }
}));

// ==========================================================
// Bayyinah | Prepare Processed Books Log
// تسجيل الكتب كـ success فقط بعد التأكد من:
// 1) اكتمال جميع Chunks
// 2) تجهيز جميع نقاط Qdrant
// 3) إرسال جميع Qdrant Batches
// 4) نجاح جميع عمليات Qdrant Upsert
// ==========================================================


// ==========================================================
// 0) قراءة بيانات مراحل الـPipeline
// ==========================================================

const parsedChunks =
  $('Parse JSONL Chunks').all();

const preparedPoints =
  $('Prepare Qdrant Points').all();

const qdrantBatches =
  $('Build Qdrant Batches').all();

const qdrantResponses =
  $input.all();

const newFiles =
  $('Filter Already Processed Files').all();


if (!newFiles.length) {
  return [];
}

if (!parsedChunks.length) {
  throw new Error(
    'لا توجد Chunks خارجة من Parse JSONL Chunks.'
  );
}

if (!preparedPoints.length) {
  throw new Error(
    'لا توجد نقاط خارجة من Prepare Qdrant Points.'
  );
}

if (!qdrantBatches.length) {
  throw new Error(
    'لا توجد دفعات خارجة من Build Qdrant Batches.'
  );
}

if (!qdrantResponses.length) {
  throw new Error(
    'لم تصل أي استجابة من Qdrant Upsert Points.'
  );
}


// ==========================================================
// 1) التحقق من أن كل Chunk أصبح Qdrant Point
// ==========================================================

if (preparedPoints.length !== parsedChunks.length) {

  throw new Error(
    `عدد نقاط Qdrant المجهزة لا يساوي عدد Chunks: ` +
    `Chunks=${parsedChunks.length}، ` +
    `Points=${preparedPoints.length}.`
  );
}


// ==========================================================
// 2) حساب عدد النقاط الموجودة داخل جميع Qdrant Batches
// ==========================================================

let totalBatchedPoints = 0;

for (let i = 0; i < qdrantBatches.length; i++) {

  const batch =
    qdrantBatches[i].json || {};

  const points =
    Array.isArray(batch.points)
      ? batch.points
      : null;

  if (!points) {
    throw new Error(
      `دفعة Qdrant رقم ${i} لا تحتوي على points.`
    );
  }

  if (!points.length) {
    throw new Error(
      `دفعة Qdrant رقم ${i} فارغة.`
    );
  }

  if (
    batch.batch_size != null &&
    Number(batch.batch_size) !== points.length
  ) {
    throw new Error(
      `عدم تطابق batch_size في دفعة Qdrant رقم ${i}: ` +
      `batch_size=${batch.batch_size}، ` +
      `points=${points.length}.`
    );
  }

  totalBatchedPoints +=
    points.length;
}


if (totalBatchedPoints !== preparedPoints.length) {

  throw new Error(
    `عدد النقاط داخل Qdrant Batches لا يساوي ` +
    `عدد النقاط المجهزة: ` +
    `Batched=${totalBatchedPoints}، ` +
    `Prepared=${preparedPoints.length}.`
  );
}


// ==========================================================
// 3) التحقق من عدد استجابات Qdrant
// ==========================================================

if (qdrantResponses.length !== qdrantBatches.length) {

  throw new Error(
    `لم تكتمل جميع دفعات Qdrant: ` +
    `الدفعات المرسلة=${qdrantBatches.length}، ` +
    `الاستجابات=${qdrantResponses.length}.`
  );
}


// ==========================================================
// 4) التحقق من نجاح كل استجابة من Qdrant
// ==========================================================

for (let i = 0; i < qdrantResponses.length; i++) {

  const response =
    qdrantResponses[i].json || {};

  const status =
    String(response.status || '')
      .trim()
      .toLowerCase();

  const operationStatus =
    String(response.result?.status || '')
      .trim()
      .toLowerCase();

  if (status !== 'ok') {

    throw new Error(
      `فشلت استجابة Qdrant للدفعة رقم ${i}. ` +
      `status="${response.status ?? 'missing'}"`
    );
  }

  if (operationStatus !== 'completed') {

    throw new Error(
      `عملية Qdrant للدفعة رقم ${i} لم تكتمل. ` +
      `result.status="${response.result?.status ?? 'missing'}"`
    );
  }
}


// ==========================================================
// 5) بناء خريطة الكتب من Chunks الأصلية
// ==========================================================

const booksMap =
  new Map();

for (const item of parsedChunks) {

  const metadata =
    item.json?.metadata &&
    typeof item.json.metadata === 'object'
      ? item.json.metadata
      : {};

  const fileId =
    String(
      metadata.drive_file_id || ''
    ).trim();

  const fileName =
    String(
      metadata.drive_file_name || ''
    ).trim();

  const documentId =
    String(
      metadata.document_id || ''
    ).trim();


  if (!fileId) {

    throw new Error(
      'تم العثور على Chunk بدون metadata.drive_file_id.'
    );
  }


  if (!fileName) {

    throw new Error(
      `تم العثور على Chunk بدون metadata.drive_file_name. ` +
      `file_id="${fileId}"`
    );
  }


  if (!documentId) {

    throw new Error(
      `تم العثور على Chunk بدون metadata.document_id. ` +
      `الملف="${fileName}"`
    );
  }


  if (!booksMap.has(fileId)) {

    booksMap.set(
      fileId,
      {
        file_id:
          fileId,

        file_name:
          fileName,

        document_id:
          documentId,

        chunk_count:
          1
      }
    );

    continue;
  }


  const existing =
    booksMap.get(fileId);


  if (
    existing.document_id !== documentId
  ) {

    throw new Error(
      `تعارض في هوية الكتاب: ` +
      `Google Drive file_id="${fileId}" ` +
      `مرتبط بأكثر من document_id: ` +
      `"${existing.document_id}" و "${documentId}".`
    );
  }


  if (
    existing.file_name !== fileName
  ) {

    throw new Error(
      `تعارض في اسم ملف Google Drive للمعرف "${fileId}". ` +
      `"${existing.file_name}" مقابل "${fileName}".`
    );
  }


  existing.chunk_count += 1;
}


// ==========================================================
// 6) التحقق من الملفات المتوقع معالجتها
// ==========================================================

const expectedFileIds =
  new Set();

for (const file of newFiles) {

  const fileId =
    String(
      file.json?.id || ''
    ).trim();

  const fileName =
    String(
      file.json?.name || ''
    ).trim();


  if (!fileId) {

    throw new Error(
      'أحد الملفات الخارجة من Filter Already Processed Files لا يحتوي على id.'
    );
  }


  if (expectedFileIds.has(fileId)) {

    throw new Error(
      `تم العثور على Google Drive file_id مكرر ضمن الملفات الجديدة: ${fileId}`
    );
  }


  expectedFileIds.add(fileId);


  if (!booksMap.has(fileId)) {

    throw new Error(
      `الملف "${fileName}" لم يظهر ضمن Chunks المعالجة. ` +
      `لن يتم تسجيله كملف ناجح.`
    );
  }
}


// ==========================================================
// 7) حماية عكسية
// لا نسمح بوجود Chunks لملفات لم تكن ضمن الملفات الجديدة
// ==========================================================

for (const fileId of booksMap.keys()) {

  if (!expectedFileIds.has(fileId)) {

    throw new Error(
      `تم العثور على Chunks لملف غير موجود ` +
      `ضمن قائمة الملفات الجديدة: ${fileId}`
    );
  }
}


// ==========================================================
// 8) التحقق من تطابق عدد الكتب
// ==========================================================

if (
  booksMap.size !==
  expectedFileIds.size
) {

  throw new Error(
    `عدم تطابق عدد الكتب: ` +
    `الملفات الجديدة=${expectedFileIds.size}، ` +
    `الكتب المعالجة=${booksMap.size}.`
  );
}


// ==========================================================
// 9) تحقق إضافي:
// مجموع Chunks الخاصة بالكتب = جميع Chunks
// ==========================================================

let totalBookChunks = 0;

for (const book of booksMap.values()) {

  totalBookChunks +=
    book.chunk_count;
}


if (
  totalBookChunks !==
  parsedChunks.length
) {

  throw new Error(
    `عدم تطابق مجموع Chunks الخاصة بالكتب: ` +
    `المجموع=${totalBookChunks}، ` +
    `Parsed=${parsedChunks.length}.`
  );
}


// ==========================================================
// 10) إنشاء سجل نجاح واحد لكل كتاب
// ==========================================================

const processedAt =
  new Date().toISOString();

const result = [];


for (const file of newFiles) {

  const fileId =
    String(
      file.json.id
    ).trim();

  const book =
    booksMap.get(fileId);


  result.push({

    json: {

      file_id:
        book.file_id,

      file_name:
        book.file_name,

      document_id:
        book.document_id,

      processed_at:
        processedAt,

      status:
        'success'
    }
  });
}


// ==========================================================
// 11) التحقق النهائي
// ==========================================================

if (
  result.length !==
  newFiles.length
) {

  throw new Error(
    `فشل التحقق النهائي من سجل الكتب المعالجة: ` +
    `الملفات=${newFiles.length}، ` +
    `السجلات=${result.length}.`
  );
}


return result;

// ==========================================================
// Bayyinah | Build Qdrant Batches
// تجميع نقاط Qdrant في دفعات للإرسال الجماعي
// ==========================================================

const items = $input.all();

if (!items.length) {
  return [];
}

// نبدأ بـ 10 نقاط لكل طلب للاستقرار.
// يمكن رفع العدد لاحقًا بعد التأكد من التشغيل الكامل.
const BATCH_SIZE = 10;

const EXPECTED_VECTOR_SIZE = 1024;

const output = [];

for (let start = 0; start < items.length; start += BATCH_SIZE) {

  const batchItems =
    items.slice(start, start + BATCH_SIZE);

  const points = [];

  for (let i = 0; i < batchItems.length; i++) {

    const item =
      batchItems[i].json || {};

    const pointId =
      String(item.point_id || '').trim();

    const vector =
      item.vector;

    const payload =
      item.payload &&
      typeof item.payload === 'object'
        ? item.payload
        : null;

    // ==========================================
    // التحقق من Point ID
    // ==========================================

    if (!pointId) {
      throw new Error(
        `point_id مفقود في العنصر رقم ${start + i + 1}.`
      );
    }

    // ==========================================
    // التحقق من Vector
    // ==========================================

    if (!Array.isArray(vector)) {
      throw new Error(
        `Vector غير صالح للنقطة: ${pointId}`
      );
    }

    if (vector.length !== EXPECTED_VECTOR_SIZE) {
      throw new Error(
        `حجم Vector غير صحيح للنقطة ${pointId}: ` +
        `${vector.length} بدلاً من ${EXPECTED_VECTOR_SIZE}.`
      );
    }

    const hasInvalidValue =
      vector.some(
        value =>
          typeof value !== 'number' ||
          !Number.isFinite(value)
      );

    if (hasInvalidValue) {
      throw new Error(
        `Vector يحتوي على قيمة غير صالحة للنقطة: ${pointId}`
      );
    }

    // ==========================================
    // التحقق من Payload
    // ==========================================

    if (!payload) {
      throw new Error(
        `Payload مفقود للنقطة: ${pointId}`
      );
    }

    // ==========================================
    // إنشاء Point
    // ==========================================

    points.push({
      id: pointId,

      vector: {
        dense: vector
      },

      payload
    });
  }

  if (points.length !== batchItems.length) {
    throw new Error(
      `فشل تجهيز دفعة Qdrant رقم ` +
      `${Math.floor(start / BATCH_SIZE)}.`
    );
  }

  output.push({
    json: {
      batch_index:
        Math.floor(start / BATCH_SIZE),

      batch_size:
        points.length,

      points
    }
  });
}


// ==========================================
// التحقق النهائي
// ==========================================

const totalPoints =
  output.reduce(
    (sum, batch) =>
      sum + batch.json.points.length,
    0
  );

if (totalPoints !== items.length) {
  throw new Error(
    `عدم تطابق عدد نقاط Qdrant: ` +
    `المدخلات=${items.length}، ` +
    `المجهزة=${totalPoints}.`
  );
}

return output;

// ==========================================================
// Bayyinah | Build Cohere Batches
// تجميع Chunks في دفعات لإرسالها إلى Cohere Embed API
// ==========================================================

const items = $input.all();

if (!items.length) {
  return [];
}

// حجم الدفعة
// Cohere يدعم حتى 96 نصًا في الطلب الواحد.
// نستخدم 50 كهامش آمن ومناسب للإنتاج.
const BATCH_SIZE = 25;

const output = [];

for (let start = 0; start < items.length; start += BATCH_SIZE) {

  const batchItems = items.slice(start, start + BATCH_SIZE);

  const texts = [];
  const chunks = [];

  for (const item of batchItems) {

    const json = item.json || {};
    const metadata = json.metadata || {};

    const text = String(json.text || '').trim();

    if (!text) {
      throw new Error(
        `تم العثور على Chunk فارغ داخل دفعة Cohere. ` +
        `chunk_id="${json.id || metadata.chunk_id || 'unknown'}"`
      );
    }

    // ------------------------------------------------------
    // بناء النص الذي سيدخل إلى Embedding
    // بنفس منطق العقدة الحالية
    // ------------------------------------------------------

    const embeddingText = [
      'Title: ' + String(metadata.source_title || '').trim(),

      metadata.author
        ? 'Author: ' + String(metadata.author).trim()
        : '',

      (metadata.issue_title || metadata.section_title)
        ? 'Section: ' +
          String(
            metadata.issue_title ||
            metadata.section_title
          ).trim()
        : '',

      metadata.issue_number != null
        ? 'Section number: ' +
          String(metadata.issue_number)
        : '',

      'Content: ' + text,
    ]
      .filter(Boolean)
      .join('\n');

    texts.push(embeddingText);

    // ------------------------------------------------------
    // الاحتفاظ بالـChunk الأصلي كاملًا
    // حتى نعيد ربط كل Vector به بعد Cohere
    // ------------------------------------------------------

    chunks.push(json);
  }

  if (texts.length !== chunks.length) {
    throw new Error(
      'حدث عدم تطابق بين عدد النصوص وعدد Chunks داخل دفعة Cohere.'
    );
  }

  output.push({
    json: {
      batch_index: Math.floor(start / BATCH_SIZE),
      batch_size: batchItems.length,
      texts,
      chunks,
    }
  });
}

return output;

// ==========================================================
// Bayyinah | Expand Jina Batch Embeddings
// فك استجابات Jina المجمعة وإعادة كل Vector إلى Chunk الصحيح
// Production Hardened Version
// ==========================================================

const responses = $input.all();
const batches = $('Build Gemini Batches').all();

const EXPECTED_VECTOR_SIZE = 1024;

if (!responses.length) {
  return [];
}

if (!batches.length) {
  throw new Error(
    'لا توجد بيانات من Build Gemini Batches.'
  );
}


// ==========================================================
// 1) التحقق من وصول استجابة لكل Batch
// ==========================================================

if (responses.length !== batches.length) {
  throw new Error(
    `عدد استجابات Jina لا يساوي عدد الدفعات: ` +
    `الدفعات=${batches.length}، ` +
    `الاستجابات=${responses.length}.`
  );
}


const output = [];


// ==========================================================
// 2) معالجة كل استجابة Jina
// ==========================================================

for (let i = 0; i < responses.length; i++) {

  const response = responses[i].json || {};
  const batch = batches[i].json || {};

  const chunks = Array.isArray(batch.chunks)
    ? batch.chunks
    : [];


  // Jina Embeddings API:
  //
  // {
  //   data: [
  //     {
  //       index: 0,
  //       embedding: [...]
  //     },
  //     {
  //       index: 1,
  //       embedding: [...]
  //     }
  //   ],
  //   model: "...",
  //   usage: {...}
  // }

  const embeddings = Array.isArray(response.data)
    ? response.data
    : null;


  // ========================================================
  // 3) التحقق من بيانات Batch الأصلية
  // ========================================================

  if (!chunks.length) {
    throw new Error(
      `الدفعة رقم ${i} لا تحتوي على chunks.`
    );
  }


  // ========================================================
  // 4) التحقق من استجابة Jina
  // ========================================================

  if (!embeddings) {
    throw new Error(
      `استجابة Jina للدفعة رقم ${i} ` +
      `لا تحتوي على data.`
    );
  }


  if (embeddings.length !== chunks.length) {
    throw new Error(
      `عدم تطابق في الدفعة رقم ${i}: ` +
      `عدد Chunks=${chunks.length}، ` +
      `عدد Embeddings=${embeddings.length}.`
    );
  }


  // ========================================================
  // 5) ترتيب Embeddings حسب index
  // لضمان مطابقة كل Vector بالـChunk الصحيح
  // ========================================================

  const sortedEmbeddings = [...embeddings].sort(
    (a, b) => {

      const indexA =
        Number.isInteger(a?.index)
          ? a.index
          : 0;

      const indexB =
        Number.isInteger(b?.index)
          ? b.index
          : 0;

      return indexA - indexB;
    }
  );


  // ========================================================
  // 6) إعادة ربط كل Embedding بالـChunk الأصلي
  // ========================================================

  for (let j = 0; j < chunks.length; j++) {

    const chunk = chunks[j];

    const embeddingObject =
      sortedEmbeddings[j] || {};

    const vector =
      embeddingObject.embedding;


    if (!Array.isArray(vector)) {
      throw new Error(
        `Embedding غير صالح في الدفعة ${i}، ` +
        `العنصر ${j}.`
      );
    }


    if (vector.length !== EXPECTED_VECTOR_SIZE) {
      throw new Error(
        `حجم Jina Embedding غير صحيح ` +
        `في الدفعة ${i}، العنصر ${j}. ` +
        `المتوقع=${EXPECTED_VECTOR_SIZE}، ` +
        `الموجود=${vector.length}.`
      );
    }


    const hasInvalidValue = vector.some(
      value =>
        typeof value !== 'number' ||
        !Number.isFinite(value)
    );


    if (hasInvalidValue) {
      throw new Error(
        `Jina Embedding يحتوي على قيمة غير صالحة ` +
        `في الدفعة ${i}، العنصر ${j}.`
      );
    }


    // التحقق من index الذي أعاده Jina
    if (
      Number.isInteger(embeddingObject.index) &&
      embeddingObject.index !== j
    ) {
      throw new Error(
        `عدم تطابق Jina index في الدفعة ${i}: ` +
        `المتوقع=${j}، ` +
        `الموجود=${embeddingObject.index}.`
      );
    }


    output.push({

      json: {

        ...chunk,

        embedding: vector,

        embedding_metadata: {

          provider:
            'jina',

          model:
            'jina-embeddings-v3',

          dimensions:
            EXPECTED_VECTOR_SIZE,

          task_type:
            'retrieval.passage',

          batch_index:
            batch.batch_index ?? i,

          position_in_batch:
            j
        }
      }
    });
  }
}


// ==========================================================
// 7) حساب العدد الحقيقي المتوقع لجميع Chunks
// ==========================================================

const expectedChunks = batches.reduce(
  (sum, item) => {

    const chunks =
      Array.isArray(item.json?.chunks)
        ? item.json.chunks
        : [];

    return sum + chunks.length;

  },
  0
);


// ==========================================================
// 8) التحقق النهائي
// لا يسمح بفقد أي Chunk أثناء Jina Embedding
// ==========================================================

if (output.length !== expectedChunks) {

  throw new Error(
    `فشل التحقق النهائي من Jina: ` +
    `المتوقع=${expectedChunks} Chunk، ` +
    `الموجود=${output.length}.`
  );
}


// ==========================================================
// 9) النتيجة النهائية
// ==========================================================

return output;

// ==========================================================
// Bayyinah | Prepare Jina Qdrant Points
// تجهيز كل Chunk + Jina Embedding كنقطة جاهزة لـ Qdrant
// Production Hardened Version
// ==========================================================

const items = $input.all();

const EXPECTED_VECTOR_SIZE = 1024;
const EXPECTED_PROVIDER = 'jina';
const EXPECTED_MODEL = 'jina-embeddings-v3';
const EXPECTED_TASK_TYPE = 'retrieval.passage';

if (!items.length) {
  return [];
}

const results = [];
const seenPointIdentities = new Set();
const seenPointIds = new Set();


// ==========================================================
// إنشاء UUID ثابت Deterministic
// الهوية = document_id + chunk_id
// ==========================================================

function createDeterministicUuid(input) {

  const text = String(input);

  let h1 = 0xdeadbeef ^ text.length;
  let h2 = 0x41c6ce57 ^ text.length;
  let h3 = 0xc0decafe ^ text.length;
  let h4 = 0x1234567 ^ text.length;

  for (let i = 0; i < text.length; i++) {

    const ch = text.charCodeAt(i);

    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
    h3 = Math.imul(h3 ^ ch, 2246822507);
    h4 = Math.imul(h4 ^ ch, 3266489909);
  }

  h1 =
    Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^
    Math.imul(h2 ^ (h2 >>> 13), 3266489909);

  h2 =
    Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^
    Math.imul(h3 ^ (h3 >>> 13), 3266489909);

  h3 =
    Math.imul(h3 ^ (h3 >>> 16), 2246822507) ^
    Math.imul(h4 ^ (h4 >>> 13), 3266489909);

  h4 =
    Math.imul(h4 ^ (h4 >>> 16), 2246822507) ^
    Math.imul(h1 ^ (h1 >>> 13), 3266489909);

  const hex =
    (h1 >>> 0).toString(16).padStart(8, '0') +
    (h2 >>> 0).toString(16).padStart(8, '0') +
    (h3 >>> 0).toString(16).padStart(8, '0') +
    (h4 >>> 0).toString(16).padStart(8, '0');

  return (
    hex.slice(0, 8) + '-' +
    hex.slice(8, 12) + '-' +
    '4' + hex.slice(13, 16) + '-' +
    '8' + hex.slice(17, 20) + '-' +
    hex.slice(20, 32)
  );
}


// ==========================================================
// معالجة جميع Chunks
// ==========================================================

for (let i = 0; i < items.length; i++) {

  const item = items[i].json || {};

  // ========================================================
  // 1) التحقق من Jina Vector
  // ========================================================

  const vector = item.embedding;

  if (!Array.isArray(vector)) {
    throw new Error(
      `لم يتم العثور على embedding صالح في العنصر رقم ${i + 1}.`
    );
  }

  if (vector.length !== EXPECTED_VECTOR_SIZE) {
    throw new Error(
      `حجم Jina Vector غير صحيح في العنصر رقم ${i + 1}: ` +
      `${vector.length} بدلاً من ${EXPECTED_VECTOR_SIZE}.`
    );
  }

  const hasInvalidVectorValue = vector.some(
    value =>
      typeof value !== 'number' ||
      !Number.isFinite(value)
  );

  if (hasInvalidVectorValue) {
    throw new Error(
      `يحتوي Jina Vector على قيمة غير رقمية أو غير صالحة ` +
      `في العنصر رقم ${i + 1}.`
    );
  }


  // ========================================================
  // 2) التحقق من Embedding Lineage
  // ========================================================

  const embeddingMetadata =
    item.embedding_metadata &&
    typeof item.embedding_metadata === 'object'
      ? item.embedding_metadata
      : {};

  const provider =
    String(
      embeddingMetadata.provider ||
      EXPECTED_PROVIDER
    ).trim();

  const model =
    String(
      embeddingMetadata.model ||
      EXPECTED_MODEL
    ).trim();

  const dimensions =
    Number(
      embeddingMetadata.dimensions ??
      EXPECTED_VECTOR_SIZE
    );

  const taskType =
    String(
      embeddingMetadata.task_type ||
      EXPECTED_TASK_TYPE
    ).trim();

  if (provider !== EXPECTED_PROVIDER) {
    throw new Error(
      `Embedding provider غير صحيح في العنصر ${i + 1}: ` +
      `"${provider}" بدلاً من "${EXPECTED_PROVIDER}".`
    );
  }

  if (model !== EXPECTED_MODEL) {
    throw new Error(
      `Embedding model غير صحيح في العنصر ${i + 1}: ` +
      `"${model}" بدلاً من "${EXPECTED_MODEL}".`
    );
  }

  if (dimensions !== EXPECTED_VECTOR_SIZE) {
    throw new Error(
      `Embedding dimensions غير صحيحة في العنصر ${i + 1}: ` +
      `${dimensions} بدلاً من ${EXPECTED_VECTOR_SIZE}.`
    );
  }

  if (taskType !== EXPECTED_TASK_TYPE) {
    throw new Error(
      `Embedding task_type غير صحيح في العنصر ${i + 1}: ` +
      `"${taskType}" بدلاً من "${EXPECTED_TASK_TYPE}".`
    );
  }


  // ========================================================
  // 3) قراءة Chunk
  // ========================================================

  const chunkId =
    String(item.id || '').trim();

  if (!chunkId) {
    throw new Error(
      `لا يوجد id للـ Chunk في العنصر رقم ${i + 1}.`
    );
  }

  const content =
    String(item.text || '').trim();

  if (!content) {
    throw new Error(
      `النص فارغ في الـ Chunk: ${chunkId}`
    );
  }


  // ========================================================
  // 4) Metadata
  // ========================================================

  const metadata =
    item.metadata &&
    typeof item.metadata === 'object'
      ? item.metadata
      : {};

  const documentId =
    String(metadata.document_id || '').trim();

  if (!documentId) {
    throw new Error(
      `document_id مفقود في الـ Chunk: ${chunkId}`
    );
  }

  const sourceTitle =
    String(metadata.source_title || '').trim();

  if (!sourceTitle) {
    throw new Error(
      `source_title مفقود في الـ Chunk: ${chunkId}`
    );
  }

  const sourceType =
    String(metadata.source_type || 'book').trim();

  const language =
    String(metadata.language || 'ar').trim();

  const pdfPages =
    Array.isArray(metadata.pdf_pages)
      ? metadata.pdf_pages
      : [];

  const printedPages =
    Array.isArray(metadata.printed_pages)
      ? metadata.printed_pages
      : [];


  // ========================================================
  // 5) الهوية المركبة للنقطة
  // ========================================================

  const pointIdentity =
    `${documentId}::${chunkId}`;

  if (seenPointIdentities.has(pointIdentity)) {
    throw new Error(
      `تم اكتشاف point_identity مكرر: ${pointIdentity}`
    );
  }

  seenPointIdentities.add(pointIdentity);


  // ========================================================
  // 6) UUID ثابت
  // ========================================================

  const pointId =
    createDeterministicUuid(pointIdentity);

  if (seenPointIds.has(pointId)) {
    throw new Error(
      `تم اكتشاف point_id مكرر: ${pointId} ` +
      `للهوية ${pointIdentity}`
    );
  }

  seenPointIds.add(pointId);


  // ========================================================
  // 7) إنشاء Qdrant Point
  // ========================================================

  results.push({

    json: {

      point_id:
        pointId,

      point_identity:
        pointIdentity,

      document_id:
        documentId,

      chunk_id:
        chunkId,

      vector,

      payload: {

        // المحتوى
        content,

        // هوية المصدر
        document_id:
          documentId,

        work_id:
          metadata.work_id || '',

        source_title:
          sourceTitle,

        source_type:
          sourceType,

        author:
          metadata.author || '',

        language:
          language,

        // بنية الكتاب
        unit_type:
          metadata.unit_type || '',

        unit_number:
          metadata.unit_number ?? null,

        question:
          metadata.question || '',

        issue_number:
          metadata.issue_number ?? null,

        issue_title:
          metadata.issue_title || '',

        section_title:
          metadata.section_title ||
          metadata.issue_title ||
          '',

        // الصفحات
        pdf_pages:
          pdfPages,

        printed_pages:
          printedPages,

        page_start:
          metadata.page_start ??
          (
            printedPages.length
              ? printedPages[0]
              : (
                  pdfPages.length
                    ? pdfPages[0]
                    : null
                )
          ),

        page_end:
          metadata.page_end ??
          (
            printedPages.length
              ? printedPages[printedPages.length - 1]
              : (
                  pdfPages.length
                    ? pdfPages[pdfPages.length - 1]
                    : null
                )
          ),

        // هوية Chunk
        chunk_id:
          chunkId,

        point_identity:
          pointIdentity,

        chunk_index:
          metadata.chunk_index ?? null,

        total_chunks_in_unit:
          metadata.total_chunks_in_unit ?? null,

        parent_id:
          metadata.parent_id || '',

        // Google Drive Lineage
        drive_file_id:
          metadata.drive_file_id || '',

        drive_file_name:
          metadata.drive_file_name || '',

        // Lineage / Processing
        dataset:
          metadata.dataset || '',

        processing_version:
          metadata.processing_version || '',

        rag_ready:
          metadata.rag_ready ?? true,

        docling_refs:
          Array.isArray(metadata.docling_refs)
            ? metadata.docling_refs
            : [],

        // Jina Embedding Lineage
        embedding_provider:
          EXPECTED_PROVIDER,

        embedding_model:
          EXPECTED_MODEL,

        embedding_dimensions:
          EXPECTED_VECTOR_SIZE,

        embedding_task_type:
          EXPECTED_TASK_TYPE,

        // سياسات جودة المصدر
        has_special_quran_glyphs:
          metadata.has_special_quran_glyphs ?? false,

        quran_special_font_policy:
          metadata.quran_special_font_policy || ''
      }
    }
  });
}


// ==========================================================
// 8) التحقق النهائي
// ==========================================================

if (results.length !== items.length) {
  throw new Error(
    `فشل التحقق النهائي في Prepare Jina Qdrant Points: ` +
    `المدخلات=${items.length}، النتائج=${results.length}.`
  );
}

return results;

// ==========================================================
// Bayyinah | Parse Citation Verification
// تحليل نتيجة Citation Verification وإنتاج مقاييس قابلة للقياس
//
// Zero-based evidence indexes only.
// ==========================================================

const input = $input.first().json;


// ==========================================================
// 1) قراءة ناتج Citation Verification
// ==========================================================

let raw =
  input.output ??
  input.text ??
  input.response ??
  '';

raw = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let result;

try {
  result = JSON.parse(raw);
} catch (error) {
  throw new Error(
    'تعذر قراءة ناتج Citation Verification كـ JSON.\n\nالناتج:\n' + raw
  );
}


// ==========================================================
// 2) التحقق من verification
// ==========================================================

const allowedVerifications = [
  'PASS',
  'REVISE',
  'NEEDS_HUMAN_REVIEW'
];

if (!allowedVerifications.includes(result.verification)) {
  throw new Error(
    'قيمة verification غير صحيحة: ' + result.verification
  );
}


// ==========================================================
// 3) استرجاع سياق الإجابة
//
// أول تشغيل:
// Parse Grounded Answer
//
// بعد المراجعة:
// Store Revised Answer Context
// ==========================================================

function getNodeJson(nodeName) {
  try {
    return $(nodeName).first().json || null;
  } catch (error) {
    return null;
  }
}

const revisedContext =
  getNodeJson('Store Revised Answer Context');

const originalContext =
  getNodeJson('Parse Grounded Answer');

const context =
  revisedContext ||
  originalContext ||
  {};


// ==========================================================
// 4) قراءة الأدلة الأصلية
// ==========================================================

const combinedEvidence =
  Array.isArray(context.combined_evidence)
    ? context.combined_evidence
    : [];

const sourcesUsed =
  Array.isArray(context.sources_used)
    ? context.sources_used
    : [];


// ==========================================================
// 5) تنظيف Claim Verifications
// ==========================================================

const rawClaimVerifications =
  Array.isArray(result.claim_verifications)
    ? result.claim_verifications
    : [];

const claimVerifications =
  rawClaimVerifications.map((claim, index) => {

    const evidenceIndexes =
      Array.isArray(claim.evidence_indexes)
        ? [
            ...new Set(
              claim.evidence_indexes
                .map(value => Number(value))
                .filter(value =>
                  Number.isInteger(value) &&
                  value >= 0 &&
                  value < combinedEvidence.length
                )
            )
          ]
        : [];

    const sourcePages =
      Array.isArray(claim.source_pages)
        ? [
            ...new Set(
              claim.source_pages.filter(
                value =>
                  value !== null &&
                  value !== undefined &&
                  String(value).trim() !== ''
              )
            )
          ]
        : [];

    return {
      claim_index: index,

      claim:
        String(claim.claim || '').trim(),

      supported:
        claim.supported === true,

      evidence_indexes:
        evidenceIndexes,

      source_pages:
        sourcePages,

      note:
        String(claim.note || '').trim()
    };
  });


// ==========================================================
// 6) تنظيف Citation Checks
// ==========================================================

const rawCitationChecks =
  Array.isArray(result.citation_checks)
    ? result.citation_checks
    : [];

const citationChecks =
  rawCitationChecks.map((citation, index) => {

    const matchedEvidenceIndexes =
      Array.isArray(citation.matched_evidence_indexes)
        ? [
            ...new Set(
              citation.matched_evidence_indexes
                .map(value => Number(value))
                .filter(value =>
                  Number.isInteger(value) &&
                  value >= 0 &&
                  value < combinedEvidence.length
                )
            )
          ]
        : [];

    return {
      source_index:
        Number.isInteger(Number(citation.source_index))
          ? Number(citation.source_index)
          : index,

      valid:
        citation.valid === true,

      supports_answer:
        citation.supports_answer === true,

      matched_evidence_indexes:
        matchedEvidenceIndexes,

      issues:
        Array.isArray(citation.issues)
          ? citation.issues
          : []
    };
  });


// ==========================================================
// 7) حساب Groundedness بصورة حتمية
//
// لا نعتمد فقط على الرقم الذي أرجعه النموذج.
// نحسبه من claim_verifications نفسها.
// ==========================================================

const totalClaims =
  claimVerifications.length;

const supportedClaimsCount =
  claimVerifications.filter(
    claim => claim.supported === true
  ).length;

const groundednessScore =
  totalClaims > 0
    ? supportedClaimsCount / totalClaims
    : 0;


// ==========================================================
// 8) حساب Citation Correctness بصورة حتمية
// ==========================================================

const totalCitations =
  citationChecks.length;

const validSupportingCitations =
  citationChecks.filter(
    citation =>
      citation.valid === true &&
      citation.supports_answer === true
  ).length;

let citationCorrectnessScore;

if (totalCitations > 0) {

  citationCorrectnessScore =
    validSupportingCitations /
    totalCitations;

} else {

  // إذا ذكرت الإجابة مصادر لكن المدقق لم ينتج citation_checks
  // نعتبر التحقق غير ناجح.
  if (sourcesUsed.length > 0) {
    citationCorrectnessScore = 0;
  } else {
    citationCorrectnessScore = 1;
  }
}


// ==========================================================
// 9) تقريب المقاييس
// ==========================================================

const roundScore = value =>
  Math.round(value * 10000) / 10000;

const finalGroundednessScore =
  roundScore(groundednessScore);

const finalCitationCorrectnessScore =
  roundScore(citationCorrectnessScore);


// ==========================================================
// 10) confidence
// ==========================================================

let confidence =
  Number(result.confidence);

if (!Number.isFinite(confidence)) {
  confidence = 0;
}

confidence =
  Math.max(
    0,
    Math.min(1, confidence)
  );


// ==========================================================
// 11) Unsupported Claims
// ==========================================================

const unsupportedClaimsFromChecks =
  claimVerifications
    .filter(claim => !claim.supported)
    .map(claim => claim.claim)
    .filter(Boolean);

const unsupportedClaimsFromModel =
  Array.isArray(result.unsupported_claims)
    ? result.unsupported_claims
        .map(value => String(value).trim())
        .filter(Boolean)
    : [];

const unsupportedClaims =
  [
    ...new Set([
      ...unsupportedClaimsFromChecks,
      ...unsupportedClaimsFromModel
    ])
  ];


// ==========================================================
// 12) Required Corrections
// ==========================================================

const requiredCorrections =
  Array.isArray(result.required_corrections)
    ? result.required_corrections
        .map(value => String(value).trim())
        .filter(Boolean)
    : [];


// ==========================================================
// 13) التحقق من اتساق القرار
// ==========================================================

let verification =
  result.verification;


// لا نسمح بـ PASS إذا كان هناك ادعاء غير مدعوم

if (
  verification === 'PASS' &&
  unsupportedClaims.length > 0
) {
  verification = 'REVISE';
}


// لا نسمح بـ PASS إذا كانت هناك Citation غير صحيحة

const hasInvalidCitation =
  citationChecks.some(
    citation =>
      citation.valid !== true ||
      citation.supports_answer !== true
  );

if (
  verification === 'PASS' &&
  hasInvalidCitation
) {
  verification = 'REVISE';
}


// ==========================================================
// 14) الحقول المنطقية النهائية
// ==========================================================

const needsRevision =
  verification === 'REVISE';

const needsHumanReview =
  verification === 'NEEDS_HUMAN_REVIEW';


// ==========================================================
// 15) إخراج النتيجة
//
// نحافظ على سياق الإجابة حتى تستطيع العقد التالية استخدام:
// question
// answer_ar
// combined_evidence
// sources_used
// supported_points
// missing_points
// ...إلخ
// ==========================================================

return [{
  json: {

    ...context,

    citation_verification:
      verification,

    verification,

    citation_verification_confidence:
      confidence,

    groundedness_score:
      finalGroundednessScore,

    citation_correctness_score:
      finalCitationCorrectnessScore,

    total_claims:
      totalClaims,

    supported_claims_count:
      supportedClaimsCount,

    unsupported_claims_count:
      totalClaims - supportedClaimsCount,

    total_citations:
      totalCitations,

    valid_supporting_citations:
      validSupportingCitations,

    needs_revision:
      needsRevision,

    needs_human_review:
      needsHumanReview,

    citation_verification_reason:
      String(result.reason || '').trim(),

    claim_verifications:
      claimVerifications,

    citation_checks:
      citationChecks,

    unsupported_claims:
      unsupportedClaims,

    required_corrections:
      requiredCorrections,

    // نحفظ أيضًا ما أرجعه النموذج لأغراض المقارنة والـBenchmark
    model_reported_groundedness_score:
      Number(result.groundedness_score || 0),

    model_reported_citation_correctness_score:
      Number(result.citation_correctness_score || 0)
  }
}];

const current = $input.first().json;

// السياق الأصلي من Telegram
let incoming = {};
try {
  incoming = $('Prepare Incoming Question').first().json;
} catch (error) {
  incoming = {};
}

const question = String(
  current.question ??
  incoming.question ??
  ''
).trim();

if (!question) {
  throw new Error('لم يتم العثور على السؤال الأصلي.');
}

// هذه العقدة لا تعمل إلا بعد NEEDS_EXTERNAL_SEARCH
if (
  current.decision &&
  current.decision !== 'NEEDS_EXTERNAL_SEARCH'
) {
  throw new Error(
    'Retrieval Retry استُدعي من قرار غير متوقع: ' +
    current.decision
  );
}

const originalEvidence =
  Array.isArray(current.all_retrieved_evidence)
    ? current.all_retrieved_evidence
    : Array.isArray(current.combined_evidence)
      ? current.combined_evidence
      : [];

const evidenceSummary = originalEvidence
  .slice(0, 5)
  .map((e, i) => ({
    index: i,
    score: Number(e.score || 0),
    title:
      e.source_title ||
      e.book_title ||
      e.source_name ||
      '',
    page:
      e.page_start ??
      (Array.isArray(e.printed_pages)
        ? e.printed_pages[0]
        : null),
    content: String(e.content || '').slice(0, 700)
  }));

return [{
  json: {
    question,
    original_question: question,

    chat_id:
      current.chat_id ??
      incoming.chat_id ??
      null,

    message_id:
      current.message_id ??
      incoming.message_id ??
      null,

    user_id:
      current.user_id ??
      incoming.user_id ??
      null,

    target_language:
      current.target_language ??
      incoming.target_language ??
      'ti',

    original_decision:
      current.decision || 'NEEDS_EXTERNAL_SEARCH',

    original_reason:
      current.reason || '',

    original_best_score:
      Number(current.best_score || 0),

    original_retrieved_count:
      Number(current.retrieved_count || 0),

    original_usable_count:
      Number(current.usable_count || 0),

    original_supported_points:
      Array.isArray(current.supported_points)
        ? current.supported_points
        : [],

    original_missing_points:
      Array.isArray(current.missing_points)
        ? current.missing_points
        : [],

    original_evidence:
      originalEvidence,

    original_evidence_summary:
      evidenceSummary,

    retry_attempt: 1,
    max_retry_attempts: 1
  }
}];

