parameters.jsCode:
const item = $input.first().json;

let raw = item.text ?? item.output ?? '';

raw = String(raw)
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '');

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error(
    'تعذر قراءة Query Rewriter كـ JSON.\n\n' + raw
  );
}

let ctx = {};
try {
  ctx = $('Prepare Retrieval Retry Context').first().json;
} catch (error) {
  ctx = {};
}

const retrievalQuery = String(
  parsed.retrieval_query ?? ''
).trim();

if (!retrievalQuery) {
  throw new Error('Query Rewriter لم يُرجع retrieval_query.');
}

return [{
  json: {
    ...ctx,
    retrieval_query: retrievalQuery,
    rewrite_reason: String(
      parsed.rewrite_reason ?? ''
    ).trim(),
    retry_attempt: 1
  }
}];

const response = $input.first().json;

let ctx = {};
try {
  ctx = $('Parse Rewritten Retrieval Query').first().json;
} catch (error) {
  ctx = {};
}

const embedding =
  response.data?.[0]?.embedding ??
  response.embeddings?.float?.[0] ??
  response.embedding ??
  null;

if (!Array.isArray(embedding) || embedding.length === 0) {
  throw new Error(
    'لم يتم العثور على embedding صالح في استجابة Jina.'
  );
}

if (embedding.length !== 1024) {
  throw new Error(
    'أبعاد embedding غير متوقعة: ' +
    embedding.length +
    ' بدل 1024.'
  );
}

return [{
  json: {
    ...ctx,
    query_embedding: embedding,
    retry_embedding_provider: 'jina',
    retry_embedding_model: 'jina-embeddings-v3',
    retry_embedding_task: 'retrieval.query',
    retry_embedding_dimensions: 1024
  }
}];

