parameters.jsCode:
const input = $input.first().json;

let raw = input.text || input.output || '';

raw = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let decision;
try {
  decision = JSON.parse(raw);
} catch (error) {
  throw new Error(
    'تعذر قراءة Retry Evidence Judge كـ JSON.\n\n' + raw
  );
}

const allowed = [
  'SUPPORTED',
  'NEEDS_EXTERNAL_SEARCH',
  'NEEDS_HUMAN_REVIEW'
];

if (!allowed.includes(decision.decision)) {
  throw new Error(
    'قيمة decision غير صحيحة: ' + decision.decision
  );
}

let retrieval = {};
try {
  retrieval = $('Evaluate Retry Retrieval').first().json;
} catch (error) {
  retrieval = {};
}

const allEvidence =
  Array.isArray(retrieval.evidence)
    ? retrieval.evidence
    : [];

const indexes =
  Array.isArray(decision.recommended_evidence_indexes)
    ? decision.recommended_evidence_indexes
        .map(v => Number(v))
        .filter(v => Number.isInteger(v) && v >= 0)
    : [];

let selectedEvidence = allEvidence;

if (indexes.length > 0) {
  const filtered = indexes
    .map(i => allEvidence[i])
    .filter(Boolean);

  if (filtered.length > 0) {
    selectedEvidence = filtered;
  }
}

const retryBest =
  Number(retrieval.retry_best_score || retrieval.best_score || 0);

const originalBest =
  Number(retrieval.original_best_score || 0);

const rescued =
  decision.decision === 'SUPPORTED';

return [{
  json: {
    question:
      retrieval.question || '',

    chat_id:
      retrieval.chat_id ?? null,

    message_id:
      retrieval.message_id ?? null,

    user_id:
      retrieval.user_id ?? null,

    target_language:
      retrieval.target_language ?? 'ti',

    evidence_sufficient:
      decision.evidence_sufficient === true,

    confidence:
      Number(decision.confidence || 0),

    decision:
      decision.decision,

    needs_external_search:
      decision.needs_external_search === true,

    needs_human_review:
      decision.needs_human_review === true,

    reason:
      decision.reason || '',

    supported_points:
      Array.isArray(decision.supported_points)
        ? decision.supported_points
        : [],

    missing_points:
      Array.isArray(decision.missing_points)
        ? decision.missing_points
        : [],

    recommended_evidence_indexes:
      indexes,

    combined_evidence:
      selectedEvidence,

    all_retrieved_evidence:
      allEvidence,

    best_score:
      retryBest,

    retrieved_count:
      Number(retrieval.retrieved_count || 0),

    usable_count:
      Number(retrieval.usable_count || 0),

    retrieval_query:
      retrieval.retrieval_query || '',

    rewrite_reason:
      retrieval.rewrite_reason || '',

    retry_attempt: 1,

    original_best_score:
      originalBest,

    retry_best_score:
      retryBest,

    score_delta:
      Number((retryBest - originalBest).toFixed(6)),

    retry_rescued:
      rescued,

    retrieval_stage:
      'QUERY_REWRITE_RETRY'
  }
}];
